function pb.model(ks,ls,ms)
local ns=tostring(ks)..bbf[2777]..tostring(ms and ms.atk)..bbf[2777]..tostring(ms and ms.cd)
local ps=pb._model[ns]
if ps~=nil then
return ps or nil
end
local qs,rs={},false
local ss=math.max(0.3,tonumber(ms and ms.cd)or 2)
local ts=math.min(1,(tonumber(ls and ls.n)or 1)/4)
local us,vs=pcall(pb.guess,ks)
local ws,xs={},{}
for ys,zs in ipairs(us and type(vs)==bbf[2635]and vs or{})do
if zs.hand then
ws[zs.pid]=true
end
xs[zs.pid]=zs.nums
end
for As,Bs in pairs(pb.rules(ks))do
if not ws[As]then
local Cs={}
for Ds,Es in pairs(type(xs[As])==bbf[2635]and xs[As]or{})do
Cs[Ds]=Es
end
for Fs,Gs in pairs(type(Bs.nums)==bbf[2635]and Bs.nums or{})do
