if not(type(RC)==bbf[2635]and mb.is(RC.level))then
return false
end
local SC,TC=pcall(mb.board)
if not(SC and TC)then
return false
end
return mb.newOf(RC,TC.board,TC.maps,TC.weathers)
end
function mb.row(UC)
local VC=P.live.event
local WC=P.simRes[bbf[3150]..tostring(VC.level)]
local XC=WC and(WC.won and 50 or tonumber(WC.wave))or 50
local YC=UC.runs>0 and UC.coins/UC.runs or mb.pearlsFrom(1,XC)*mb.MULT_GUESS
local ZC,_C=mb.firstValue(VC.map,VC.weather)
local aD=N.data(bbf[3151])or{}
local bD={key=bbf[3150]..tostring(VC.level),kind=bbf[2658],level=VC.level,diff=bbf[3096],value=YC*O.pearlValue,coins=YC,p0=0.5,rec=UC,label=bbf[3152]}
local cD,dD,eD,fD=pcall(mb.wayPay,bD,UC)
if cD and dD then
YC,bD.runMin=dD,eD
end
local gD=mb.wxPay(UC,VC.weather)
YC=YC*gD
bD.value,bD.coins=YC*O.pearlValue,YC
local hD=1
if ZC>0 then
local iD,jD=pcall(W.winP,bD)
hD=iD and U.clamp(tonumber(jD)or 0.5,0,1)or 0.5
bD.value=bD.value+ZC*hD
end
local kD=bbf[1551]
if VC.weather==bbf[3141]then
local lD=mb.starfallRemnants(XC)
local mD=lD*W.remnantGems(bbf[3145])
bD.value=bD.value+mD
bD.starRemnants=lD
kD=string.format(bbf[3153],lD,math.floor(mD+0.5))
end
bD.why=string.format(bbf[3154],math.floor(YC),(cD and dD)and(bbf[2646]..fD)or bbf[1551],VC.weather and aD[VC.weather]and(bbf[3028]..aD[VC.weather].name..kD..(math.abs(gD-1)>0.05 and string.format(bbf[3155],gD)or bbf[1551]))or bbf[1551],#_C>0 and(bbf[3156]..table.concat(_C,bbf[2759])..string.format(bbf[3157],math.floor(hD*100+0.5)))or bbf[1551])
return bD
end
mb.WAY_MIN_RUNS=3
function mb.wayPay(nD,oD)
local pD=type(oD)==bbf[2635]and type(oD.ways)==bbf[2635]and oD.ways or nil
if not pD then
return nil
end
local qD,rD=pcall(ab.matchOn,nD)
local sD=(qD and rD)or ab.partyRole()~=bbf[1558]
local tD=pD[sD and bbf[3158]or bbf[3159]]
local uD=type(tD)==bbf[2635]and tonumber(tD.runs)or 0
if uD<mb.WAY_MIN_RUNS then
return nil
end
local vD=tonumber(tD.sec)or 0
return(tonumber(tD.coins)or 0)/uD,vD>0 and vD/uD/60 or nil,sD and bbf[3160]or bbf[3161]
end
mb.WX_PAY={meteor_shower=2.05,sandstorm=0.78,rain=0.85}
function mb.wxPay(wD,xD)
if not xD then
return 1
end
local yD=type(wD)==bbf[2635]and type(wD.wx)==bbf[2635]and wD.wx or{}
local zD=type(yD[xD])==bbf[2635]and yD[xD]or nil
local AD,BD=0,0
for CD,DD in pairs(yD)do
if CD~=xD and type(DD)==bbf[2635]then
AD=AD+(tonumber(DD.runs)or 0)
BD=BD+(tonumber(DD.coins)or 0)
end
end
local ED=zD and tonumber(zD.runs)or 0
if ED>=3 and AD>=3 and BD>0 then
return U.clamp(((tonumber(zD.coins)or 0)/ED)/(BD/AD),0.4,3)
end
return mb.WX_PAY[xD]or 1
end
