function mb.merchantBuy()
if O.pearlRemnants~=true then
return
end
local YD=W.eventNow()
if not(YD and YD.hunt)then
return
end
local ZD,_D=F.request(bbf[3167],bbf[3168])
if not(ZD and type(_D)==bbf[2635])then
return
end
local aE=N.prof()
local bE=type(aE)==bbf[2635]and aE.bsd_shop_data
local cE=type(bE)==bbf[2635]and type(bE.bought_items)==bbf[2635]and bE.bought_items or{}
for dE,eE in pairs(_D)do
local fE=type(eE)==bbf[2635]and eE.resource_cost
if type(fE)==bbf[2635]and tostring(eE.id)==mb.REM_ITEM and fE.id==bbf[3169]then
local gE=tonumber(fE.amount)or 0
local hE=eE.stock==bbf[3170]and 99 or math.max(0,(tonumber(eE.stock)or 0)-(tonumber(cE[dE])or 0))
local iE=mb.remBuyN(N.cur(bbf[3169]),gE,hE)
local jE=0
for kE=1,math.min(iE,20)do
local lE=tonumber(N.cur(bbf[3169]))or 0
local mE=U.now()
local nE,oE=F.request(bbf[3171],bbf[3172],dE,bbf[3091])
local pE=U.now()
while U.now()-pE<3 and(tonumber(N.cur(bbf[3169]))or 0)>=lE do
task.wait(0.2)
end
if not nE or(tonumber(N.cur(bbf[3169]))or 0)>=lE then
F.log(1,bbf[3173],bbf[3174]..tostring(F.gameSaid(mE)or oE)..bbf[3175])
F.backoff(bbf[3171],900)
break
end
jE,hE=jE+1,hE-1
cb.add(bbf[3176],gE,bbf[3177],bbf[3178])
end
P.live.remLeft={n=hE,cost=gE,at=os.time()}
if jE>0 then
F.log(1,bbf[3173],string.format(bbf[3179],jE,jE==1 and bbf[1551]or bbf[2479],U.fmt(jE*gE),hE))
if F.notify then
pcall(F.notify,bbf[3180],string.format(bbf[3181],jE,jE==1 and bbf[1551]or bbf[2479]),bbf[3182])
end
end
pcall(F.saveSoon)
