local JE=type(IE)==bbf[2635]and IE._d
for KE,LE in pairs(type(JE)==bbf[2635]and JE or{})do
if type(LE)==bbf[2635]and LE._t then
HE.rolls[tostring(LE._t)]=(HE.rolls[tostring(LE._t)]or 0)+(tonumber(LE._d)or 0)
end
end
table.insert(DE,HE)
end
end
return DE
end
function mb.charmOn()
