local TE,UE,VE=QE.rolls.unit_damage or 0,QE.rolls.reward_mul or 0,0
for WE,XE in pairs(QE.rolls)do
if WE~=bbf[3191]and WE~=bbf[3192]then
VE=VE+XE
end
end
if SE>=0.92 or(O.huntPearls and RE and RE.kind==bbf[2658]and mb.is(RE.level)and SE>=0.5)then
return UE*3+TE+VE*0.5
end
return TE*3+UE+VE*0.5
end
function mb.charmWords(YE)
