return nil
end
local iF,jF
for kF,lF in ipairs(mb.charms())do
local mF=mb.charmScore(lF,hF)
if not jF or mF>jF then
iF,jF=lF,mF
end
end
if not iF then
return nil
end
local nF=mb.charmOn()or(F.where==bbf[2716]and P.charm.uuid)or nil
if nF==iF.uuid then
return nil
end
return iF,nF
end
function mb.charmTick(oF)
local pF,qF=mb.charmWant(oF)
if not pF then
return
end
qF=mb.charmOn()
