F.request(bbf[3199],bbf[3200],qF)
task.wait(1)
end
F.request(bbf[3199],bbf[3201],pF.uuid)
local rF=U.now()
while U.now()-rF<4 and mb.charmOn()~=pF.uuid do
task.wait(0.5)
end
if mb.charmOn()==pF.uuid then
P.charm.uuid,P.charm.at,P.charm.failAt=pF.uuid,os.time(),nil
F.saveSoon()
F.log(1,bbf[3202],string.format(bbf[3203],mb.charmWords(pF),tostring(oF.label),math.floor((tonumber(oF.p)or 0)*100+0.5),(tonumber(oF.p)or 0)>=0.92 and bbf[3194]or bbf[3087]))
else
