function mb.charmSlots()
return tonumber(N.GS and N.GS.MAX_CHARM_SLOTS)or 8
end
function mb.charmSellPlan(sF)
sF=sF or mb.charms()
local tF=mb.charmSlots()
local uF=math.max(1,math.min(tF-2,math.floor(tonumber(O.charmFree)or 2)))
local vF= #sF-(tF-uF)
if vF<=0 then
return{},#sF,tF,uF
end
local wF=mb.charmOn()
local xF={}
for yF,zF in ipairs(sF)do
zF.total=0
for AF,BF in pairs(zF.rolls)do
zF.total=zF.total+BF
if not xF[AF]or BF>(xF[AF].rolls[AF]or 0)then
xF[AF]=zF
end
end
end
local CF={}
for DF,EF in pairs(xF)do
CF[EF]=true
end
local FF={}
for GF,HF in ipairs(sF)do
if not CF[HF]and not HF.worn and HF.uuid~=wF and HF.tier<4 then
table.insert(FF,HF)
end
end
table.sort(FF,function(IF,JF)
if math.abs(IF.total-JF.total)>1e-9 then
return IF.total<JF.total
end
return IF.tier<JF.tier
end)
local KF={}
for LF=1,math.min(vF,#FF)do
table.insert(KF,FF[LF])
end
return KF,#sF,tF,uF
end
function mb.charmSellTick()
