table.insert(QF,mb.charmWords(SF))
end
local TF=U.now()
local UF,VF=F.request(bbf[3205],bbf[3206],PF)
while U.now()-TF<5 and#mb.charms()>NF- #PF do
task.wait(0.25)
end
local WF= #mb.charms()
if WF>NF- #PF then
local XF=F.gameSaid(TF)
F.log(1,bbf[3202],string.format(bbf[3207],#PF,tostring(XF or VF or bbf[3208])))
F.backoff(bbf[3205],1800)
return
end
cb.add(string.format(bbf[3209],#PF),#PF,bbf[3210],string.format(bbf[3211],OF-WF,OF,table.concat(QF,bbf[3212])))
end
function mb.weatherStrength(YF)
local ZF=mb.fx(YF)
local _F=ZF.dmg/ZF.cd/ZF.hp/ZF.speed*(1+(ZF.range-1)/2)
for aG,bG in pairs(ZF.kinds)do
_F=_F*(1+bb.rogueShare(aG)*bG)
end
if ZF.ice>0 then
local cG=bb.rogueShare(bbf[2786])
_F=_F*(cG+(1-cG)/(1-ZF.ice+ZF.ice/gb.modFactor(bbf[3213])))
end
if ZF.fly>0 then
_F=_F*(1-ZF.fly*0.5)
end
if ZF.noCC then
_F=_F*0.95
end
if ZF.shroud then
_F=_F*0.9
end
if ZF.zap then
_F=_F*0.85
end
return _F/mb.weatherK(YF)
end
mb.WEATHER_K_MIN,mb.WEATHER_K_MAX,mb.WEATHER_K_RUNS=0.5,4,10
function mb.weatherK(dG)
local eG=dG and type(P.hunt)==bbf[2635]and type(P.hunt.wk)==bbf[2635]and P.hunt.wk[tostring(dG)]or nil
return type(eG)==bbf[2635]and tonumber(eG.k)or 1
end
function mb.weatherLearn()
if bb.withOthers or#game:GetService(bbf[1530]):GetPlayers()>1 then
return
end
local fG=bb.huntWeather or mb.weatherNow()
local gG,hG=bb.pred,bb.calRun
if not fG or type(gG)~=bbf[2635]or type(hG)~=bbf[2635]then
return
end
local function iG(jG,kG)
return type(jG)==bbf[2635]and tonumber(jG[kG]or jG[tostring(kG)])or nil
end
local lG={}
for mG=2,bb.wave()do
local nG,oG=iG(hG.alive,mG),iG(gG.aliveAt,mG)
if nG and oG and nG>0 and oG>0 then
table.insert(lG,nG/oG)
end
end
if#lG<3 then
return
end
table.sort(lG)
local pG=lG[math.ceil(#lG/2)]
P.hunt.wk=type(P.hunt.wk)==bbf[2635]and P.hunt.wk or{}
local qG=P.hunt.wk[tostring(fG)]
local rG=math.min(mb.WEATHER_K_RUNS-1,type(qG)==bbf[2635]and tonumber(qG.n)or 0)
local sG=mb.weatherK(fG)
local tG=math.max(1,rG)
local uG=math.exp((tG*math.log(sG)+math.log(sG*pG))/(tG+1))
uG=U.clamp(uG,mb.WEATHER_K_MIN,mb.WEATHER_K_MAX)
bb.wkWas={w=tostring(fG),old=qG}
P.hunt.wk[tostring(fG)]={k=uG,n=(type(qG)==bbf[2635]and tonumber(qG.n)or 0)+1,at=os.time()}
F.log(1,bbf[3214],string.format(bbf[3215],tostring(fG),pG,tostring(fG),uG,sG,P.hunt.wk[tostring(fG)].n))
end
function mb.cardGems(vG,wG)
local xG=0
local yG=mb.pearlsFrom(wG+1,50)
for zG,AG in pairs(type(vG.effects)==bbf[2635]and vG.effects or{})do
if type(AG)==bbf[2635]then
local BG=tonumber(AG.amount)or 0
if AG.type==bbf[3216]then
xG=xG+math.abs(BG)*yG*O.pearlValue
elseif AG.type==bbf[3217]then
local CG,EG=pcall(W.rewardValue,AG.reward)
if CG then
xG=xG+(tonumber(EG)or 0)
end
elseif AG.type==bbf[3218]then
xG=xG+BG*mb.STARFALL_GEMS
elseif AG.type==bbf[3219]then
xG=xG+BG*100
end
end
end
if vG.option_type==bbf[3220]then
xG=xG+mb.HARD_GEMS
end
if vG.weather then
local FG=vG.weather~=mb.weatherNow()
if FG and vG.weather==bbf[3141]then
xG=xG+mb.starfallRemnants(50-(tonumber(wG)or 0))*W.remnantGems(bbf[3145])
end
local GG=mb.board()
if FG and GG and vG.weather~=bbf[3147]and not GG.weathers[vG.weather]then
xG=xG+(1000+5000*O.pearlValue+50*W.remnantGems(bbf[3145]))/mb.WEATHERS
end
end
return xG
end
