mb.SKIN_SET,mb.STAR=bbf[3197],bbf[3238]
mb.SKIN_PRICE={Rare=10,Epic=40,Legendary=75,Mythic=300}
mb.SKIN_DROP={Rare=0.02,Epic=0.05,Legendary=0.25,Mythic=0.4}
mb.STAR_COST=150
mb.EVENT_DROP={darkness=0.2,darkness_evolved=0.4,aqua=0.2,aqua_evolved=0.4,megumin=0.2,megumin_evolved=0.4,ishmael=0.2,ishmael_evolved=0.4,marco=0.2,marco_evolved=0.4,enel=0.2,enel_evolved=0.4,rudeus=0.2,rudeus_evolved=0.4}
function mb.unitDrop(QG,RG)
if type(QG)~=bbf[2635]then
return 0,false
end
local SG=N.data(bbf[3089])or{}
local TG=mb.EVENT_DROP[QG.unit_id]or 0
local UG=QG.skin and QG.skin._skin_id and SG[QG.skin._skin_id]
if type(UG)==bbf[2635]and UG._skin_set==mb.SKIN_SET then
return TG+(mb.SKIN_DROP[UG._skin_rarity]or 0),true
end
local VG=0
if O.skinSmart==true then
for WG,XG in ipairs(RG or{})do
if type(XG.skin)==bbf[2635]and mb.skinFits(QG.unit_id,XG.skin)then
VG=math.max(VG,mb.SKIN_DROP[XG.skin._skin_rarity]or 0)
end
end
end
return TG+VG,false
end
function mb.teamDrop(YG,ZG)
local aH=0
for bH,cH in ipairs(YG or{})do
aH=aH+(mb.unitDrop(cH,ZG))
end
return math.min(1,aH)
end
mb.BONUS_BAR,mb.BONUS_SWAPS=1.3,4
function mb.bonusTeam(dH,eH,fH)
if type(dH)~=bbf[2635]or type(eH)~=bbf[2635]or#eH==0 then
return nil
end
local gH,hH=U.now(),N.session()
fH=tonumber(fH)or 12
local iH,jH=pcall(mb.skinPlan)
local kH=iH and type(jH)==bbf[2635]and jH.kinds or{}
local function lH(mH,nH)
local oH,pH=gb.teamFrom(mH,dH.map),0
for qH,rH in ipairs({1,0.92,1.08})do
if gb.run(dH,oH,{hpMul=nH*rH}).won then
pH=pH+1
end
task.wait()
if pH>=2 then
return true
end
if qH==2 and pH==0 then
return false
end
end
return false
end
local sH=(lH(eH,mb.BONUS_BAR)and mb.BONUS_BAR)or(lH(eH,1)and 1)or nil
if not sH then
return nil
end
local tH=gb.grownKinds()>=gb.GROWN_MIN
local uH={}
for vH,wH in pairs(hH.profile_data.collection.owned_units)do
local xH=hH.collection:get_unit_by_uuid(wH.uuid)or wH
local yH=(mb.unitDrop(xH,kH))
if yH>0 and N.Units[xH.unit_id]and V.rows(xH.unit_id)and not V.hidden(xH.unit_id)then
local zH,AH=pcall(N.USC.calculate_level,xH.unit_id,tonumber(xH.xp)or 0)
if V.isFarm(xH.unit_id)or not tH or(zH and(tonumber(AH)or 0)>=gb.GROWN_LEVEL)then
local BH,CH=pcall(V.score,xH,dH.mod)
CH=(BH and tonumber(CH)or 0)*V.eventMul(xH,dH.ld)
if not uH[xH.unit_id]or CH>uH[xH.unit_id].sc then
uH[xH.unit_id]={u=xH,d=yH,sc=CH}
end
end
end
end
local DH={}
for EH,FH in pairs(uH)do
table.insert(DH,FH)
end
table.sort(DH,function(GH,HH)
if GH.d~=HH.d then
return GH.d>HH.d
end
return GH.sc>HH.sc
end)
if#DH==0 then
return nil
end
local IH,JH=table.clone(eH),{}
local KH=mb.teamDrop(IH,kH)
local LH=gb.realShares(dH.key,5)
local function MH(NH)
local OH,PH={},0
pcall(gb.run,dH,gb.teamFrom(NH,dH.map),{hpMul=1,dealt=OH})
task.wait()
for QH,RH in pairs(OH)do
PH=PH+(tonumber(RH)or 0)
end
local SH={}
for TH,UH in ipairs(NH)do
SH[UH.unit_id]=tonumber(LH[UH.unit_id])or(((tonumber(OH[V.name(UH.unit_id)])or 0)+(tonumber(OH[bbf[3239]..tostring(UH.unit_id)])or 0))/math.max(1,PH))
end
return SH
end
local VH=MH(IH)
for WH=1,mb.BONUS_SWAPS do
if mb.teamDrop(IH,kH)>=1 or U.now()-gH>fH then
break
end
local XH=false
for YH,ZH in ipairs(DH)do
if U.now()-gH>fH then
break
end
local _H=false
for aI,bI in ipairs(IH)do
if bI.uuid==ZH.u.uuid or V.sameGroup(bI.unit_id,ZH.u.unit_id)then
_H=true
break
end
end
if not _H then
local cI={}
for dI,eI in ipairs(IH)do
if(mb.unitDrop(eI,kH))<ZH.d then
table.insert(cI,{i=dI,sc=(tonumber(VH[eI.unit_id])or 0)+((V.isFarm(eI.unit_id)or V.allyBuff(eI.unit_id))and 1e300 or 0)})
end
end
table.sort(cI,function(fI,gI)
return fI.sc<gI.sc
end)
for hI=1,math.min(2,#cI)do
local iI=table.clone(IH)
local jI=iI[cI[hI].i]
iI[cI[hI].i]=ZH.u
if mb.teamDrop(iI,kH)>mb.teamDrop(IH,kH)+1e-6 and lH(iI,sH)then
table.insert(JH,string.format(bbf[3240],V.name(ZH.u.unit_id),V.name(jI.unit_id)))
IH,XH=iI,true
VH=MH(IH)
break
end
end
end
if XH then
break
end
end
if not XH then
break
end
end
if#JH==0 then
return nil
end
return IH,string.format(bbf[3241],table.concat(JH,bbf[2759]),math.floor(mb.teamDrop(IH,kH)*100+0.5),math.floor(KH*100+0.5),sH)
end
function mb.skinSet(kI)
