for QI,RI in ipairs(II)do
local SI=RI.skin and RI.skin._skin_id and yI[RI.skin._skin_id]
if not(SI and SI._skin_set==mb.SKIN_SET)then
for TI,VI in pairs(yI)do
if type(VI)==bbf[2635]and VI._skin_set==mb.SKIN_SET and mb.skinFits(RI.unit_id,VI)then
local WI=TI..bbf[3245]
if AI[WI]then
