function mb.skinTick()
if not(O.skinSmart or O.starOpen)or not(P.live.event and mb.is(P.live.event.level))then
return
end
if(F.req.back.skins or 0)>U.now()then
return
end
local FJ=N.session()
local function GJ(HJ,IJ,JJ)
local KJ=F.gameSaid(IJ)
ab.pickNote.skins=string.format(bbf[3266],HJ,tostring(KJ or JJ or bbf[3208]))
F.log(1,bbf[3164],ab.pickNote.skins)
F.backoff(bbf[3267],1800)
end
local LJ=mb.skinPlan()
if O.skinSmart then
local MJ=LJ.wear[1]
if MJ and(F.req.back.skinWear or 0)<=U.now()then
local NJ=kb.slotOf(MJ.unit)
if NJ then
P.str.reequip={uuid=MJ.unit,slot=NJ}
F.saveNow()
F.request(bbf[3268],bbf[3269],MJ.unit)
local OJ=U.now()
