task.wait(0.25)
end
end
local PJ=U.now()
local QJ,RJ=F.request(bbf[3270],bbf[3201],MJ.uuid,{unit_uuid=MJ.unit})
local function SJ()
local TJ=FJ.collection:get_unit_by_uuid(MJ.unit)
return TJ and TJ.skin~=nil
end
while U.now()-PJ<5 and not SJ()do
task.wait(0.25)
end
if NJ then
kb.reequip()
end
if SJ()then
F.log(1,bbf[3164],string.format(bbf[3271],MJ.name,MJ.unitName))
ab.pickNote.skins=nil
LJ=mb.skinPlan()
else
local UJ=F.gameSaid(PJ)
ab.pickNote.skins=string.format(bbf[3272],MJ.name,tostring(UJ or RJ or bbf[3208]))
F.log(1,bbf[3164],ab.pickNote.skins)
F.backoff(bbf[3270],1800)
end
end
if#LJ.sell>0 then
local VJ,WJ={},0
for XJ=1,math.min(50,#LJ.sell)do
table.insert(VJ,LJ.sell[XJ].uuid)
WJ=WJ+LJ.sell[XJ].pearls
end
local YJ=tonumber(N.cur(bbf[3169]))or 0
local ZJ=U.now()
local _J,aK=F.request(bbf[3273],bbf[3206],VJ)
while U.now()-ZJ<5 and(tonumber(N.cur(bbf[3169]))or 0)<=YJ do
task.wait(0.25)
end
local bK=(tonumber(N.cur(bbf[3169]))or 0)-YJ
if bK<=0 then
return GJ(bbf[3274],ZJ,aK)
end
cb.add(string.format(bbf[3275],#VJ),#VJ,bbf[3267],string.format(bbf[3276],U.fmt(bK)))
ab.pickNote.skins=nil
end
end
if O.starOpen then
local cK=FJ.inventory
local function dK()
local eK,fK=pcall(cK.get_number_of_owned_item,cK,mb.STAR)
return eK and tonumber(fK)or 0
end
local gK=U.now()
for hK=1,8 do
if U.now()-gK>15 or not F.alive or F.where~=bbf[2715]then
break
end
local iK=dK()
local jK=mb.starPlan(mb.skinPlan())
local kK=U.now()
if iK>0 then
local lK,mK=F.request(bbf[3277],bbf[3278],mb.STAR,{use10=iK>=10,use_all=false})
while U.now()-kK<6 and dK()>=iK do
task.wait(0.25)
end
if dK()>=iK then
return GJ(bbf[3279],kK,mK)
end
F.log(1,bbf[3164],string.format(bbf[3280],iK-dK(),(tonumber(((N.prof().capsule_pity_data or{})[mb.STAR]or{}).total_opens)or 0)))
ab.pickNote.skins=nil
elseif jK.open>0 then
local nK=jK.open>=10 and 10 or 1
local oK=tonumber(N.cur(bbf[3169]))or 0
local pK,qK=F.request(bbf[3281],bbf[3282],mb.STAR,bbf[2658],bbf[3283],tostring(nK))
while U.now()-kK<5 and dK()<=0 do
task.wait(0.25)
end
if dK()<=0 then
return GJ(bbf[3284],kK,qK)
end
cb.add(string.format(bbf[3285],dK()),oK-(tonumber(N.cur(bbf[3169]))or 0),bbf[3177],bbf[3286]..jK.why)
ab.pickNote.skins=nil
else
break
end
end
end
end
