function W.icWinP(jU)
local kU=jU.rec or W.rec(jU.key)
local lU=W.icLost(jU.room)
local mU=lU and lU.n or 0
local nU=((tonumber(kU.wins)or 0)+(jU.p0 or W.PRIOR_WIN.castle)*2)/((tonumber(kU.runs)or 0)+2)
local oU=W.sim(jU)
local pU,qU=0,0
if oU and tonumber(oU.p)then
local rU=type(oU.trust)==bbf[2635]and oU.trust or nil
local sU=rU~=nil and not rU.ok
local tU=sU and(tonumber(rU.ratio)or 1)>1
if not sU or(tU and not oU.won)or(sU and not tU and oU.won)then
local uU,vU=pcall(gb.styleP,oU)
pU,qU=(uU and tonumber(vU))or tonumber(oU.p),W.IC.SIM_W
end
end
return(nU*2+pU*qU)/(mU+2+qU)
end
function W.winP(wU)
