return W.MATCHED_DAILY_P
end
end
local zU=wU.rec
local AU=wU.p0 or W.PRIOR_WIN[wU.kind]or 0.7
local BU=W.sim(wU)
if BU and not(BU.trust and not BU.trust.ok)then
local CU=BU.calibrated or zU.runs>0
local DU=(BU.trust and BU.trust.ok)and 6 or(CU and 3 or 1.5)
local EU=(CU or BU.hopeless)and 0 or 2
local FU,GU=pcall(gb.styleP,BU)
