Kkb=Kkb+Mkb*math.clamp(tonumber(Ikb[Lkb])or 1,0.25,4)
end
local Nkb={}
for Okb,Pkb in pairs(Hkb)do
Nkb[Okb]=Kkb>0 and Pkb*math.clamp(tonumber(Ikb[Okb])or 1,0.25,4)*Jkb/Kkb or Pkb
end
