end
function kb.relicPlan(Qkb)
local Rkb=N.session()
if not Rkb then
return nil
end
local Skb=Rkb.inventory and Rkb.inventory.inventory_profile_data or{}
local Tkb={}
for Ukb,Vkb in ipairs(Skb.unique_items or{})do
if type(Vkb)==bbf[2635]and Vkb.uuid and(N.Items[Vkb.item_id]or{}).item_group==bbf[3706]then
table.insert(Tkb,Vkb)
end
end
local Wkb={}
local Xkb,Ykb={},{}
for Zkb,_kb in ipairs(V.equipped())do
if not V.isFarm(_kb.id)then
local alb=kb.share(_kb.id)
if not P.str.share[_kb.id]then
alb=math.min(alb,0.15)
end
Xkb[_kb.id]=alb
local blb,clb=pcall(V.elem,_kb.id,type(Qkb)==bbf[2635]and type(Qkb.weak)==bbf[2635]and{weak=Qkb.weak,strong=Qkb.strong or{},res=Qkb.res}or nil)
Ykb[_kb.id]=blb and tonumber(clb)or 1
end
end
if type(Qkb)==bbf[2635]then
Xkb=kb.modShares(Xkb,Ykb)
end
for dlb,elb in ipairs(V.equipped())do
local flb=elb.data and elb.data.rarity
if not V.isFarm(elb.id)and(flb==bbf[3243]or flb==bbf[3244]or flb==bbf[3779]or flb==bbf[3786])then
local glb=Xkb[elb.id]or kb.share(elb.id)
local hlb={}
for ilb,jlb in ipairs(Tkb)do
local klb=kb.relicWorth(elb.u,jlb)*glb*100
if klb>0.01 then
table.insert(hlb,{it=jlb,w=klb})
end
end
table.sort(hlb,function(llb,mlb)
if llb.w~=mlb.w then
return llb.w>mlb.w
end
return llb.it.uuid<mlb.it.uuid
end)
local nlb,olb={},{}
for plb,qlb in ipairs(hlb)do
local rlb=olb[qlb.it.item_id]or 0
if#nlb<6 and rlb<((N.Items[qlb.it.item_id]or{}).unique_equip and 1 or 2)then
olb[qlb.it.item_id]=rlb+1
table.insert(nlb,qlb)
end
end
if elb.u._equipped_relic then
local slb=false
for tlb,ulb in ipairs(nlb)do
if ulb.it.uuid==elb.u._equipped_relic then
slb=true
end
end
local vlb=not slb and Rkb.inventory:get_item_by_uuid(elb.u._equipped_relic)
if vlb then
table.insert(nlb,{it=vlb,w=kb.relicWorth(elb.u,vlb)*glb*100})
end
end
table.insert(Wkb,{e=elb,share=glb,opts=nlb})
end
end
local wlb,xlb={},-1
local ylb,zlb,Alb={},{},{}
local function Blb(Clb,Dlb)
if Clb> #Wkb then
if Dlb>xlb then
xlb=Dlb
wlb=table.clone(ylb)
end
return
end
local Elb=Wkb[Clb]
ylb[Elb.e.uuid]=nil
Blb(Clb+1,Dlb)
for Flb,Glb in ipairs(Elb.opts)do
local Hlb=(N.Items[Glb.it.item_id]or{}).unique_equip
if not zlb[Glb.it.uuid]and not(Hlb and Alb[Glb.it.item_id])then
zlb[Glb.it.uuid]=true
if Hlb then
Alb[Glb.it.item_id]=true
end
ylb[Elb.e.uuid]=Glb.it.uuid
Blb(Clb+1,Dlb+Glb.w+(Glb.it.uuid==Elb.e.u._equipped_relic and 0.01 or 0))
ylb[Elb.e.uuid]=nil
zlb[Glb.it.uuid]=nil
if Hlb then
Alb[Glb.it.item_id]=nil
end
end
end
end
Blb(1,0)
local Ilb,Jlb=0,{}
for Klb,Llb in ipairs(Wkb)do
local Mlb=Llb.e.u._equipped_relic and Rkb.inventory:get_item_by_uuid(Llb.e.u._equipped_relic)
local Nlb=Mlb and kb.relicWorth(Llb.e.u,Mlb)*Llb.share*100 or 0
Ilb=Ilb+Nlb
local Olb=wlb[Llb.e.uuid]and Rkb.inventory:get_item_by_uuid(wlb[Llb.e.uuid])
local Plb=Olb and kb.relicWorth(Llb.e.u,Olb)*Llb.share*100 or 0
table.insert(Jlb,string.format(bbf[3787],V.name(Llb.e.id),Mlb and(N.Items[Mlb.item_id]or{}).name or bbf[3254],Nlb,Olb and(N.Items[Olb.item_id]or{}).name or bbf[3254],Plb))
end
return wlb,xlb-Ilb,Jlb,Wkb
end
