function kb.xpRate()
local onb=N.session()
if not onb then
return 0
end
local pnb=0
for qnb,rnb in ipairs(kb.core())do
local snb=onb.collection:get_unit_by_uuid(rnb)
if snb then
local tnb,unb=kb.gainXp(snb,500000)
if unb>0 then
pnb=math.max(pnb,tnb/unb)
end
end
end
local vnb=pnb*(O.strengthValue or 300)
if(tonumber(N.cur(bbf[2710]))or 0)>(O.xpGoldFloor or 100000)then
vnb=math.min(vnb,(N.GOLD_VALUE or 0.02)/14)
end
return vnb
end
function kb.xpGuess(wnb)
local xnb=wnb.level and N.Levels[wnb.level]
if not xnb then
return 0
end
local ynb=math.min(9,tonumber(xnb.story_world_rank)or tonumber(wnb.rank)or 9)
local znb=tonumber(xnb.story_level_rank)or 6
local Anb=(wnb.kind==bbf[2684]and 1.5 or 1)*(ynb>5 and 2 or 1)
local Bnb=2.1564^(ynb-1)*(40+10*znb)/Anb
if wnb.kind==bbf[2660]then
Bnb=3*30*2.1564^(ynb-1)/Anb
end
local Cnb=ynb>=9 and 0.3 or(ynb>=7 and 0.5 or 1)
return Bnb*Cnb*6
end
function kb.modeBonus(Dnb)
