kb._xpRate,kb._xpRateAt=Enb,os.time()
end
if Enb<=0 then
return 0
end
local Fnb=P.modes and P.modes[Dnb.key]
local Gnb=tonumber(Fnb and Fnb.xp)or kb.xpGuess(Dnb)
local Hnb=Gnb*Enb
if Hnb<1 then
return 0
end
return Hnb,string.format(bbf[3802],U.fmt(Gnb),math.floor(Hnb+0.5))
end
function kb.xpSettle()
