end
local Pnb=W.rec(Inb.key)
Pnb.xp=Pnb.xp and(Pnb.xp+(Knb-Pnb.xp)*0.3)or Knb
if Knb>0 then
F.log(2,kb.LOG,string.format(bbf[3803],Inb.key,U.fmt(Knb)))
end
