cb.add(string.format(bbf[3807],hob,bob.name),hob,bbf[3808],string.format(bbf[3809],U.fmt(pob),rob))
kb.note(string.format(bbf[3810],bob.name,hob,U.fmt(pob),rob,math.abs(pob-gob)>gob*0.1 and string.format(bbf[3811],U.fmt(gob))or bbf[1551]))
