if CFb and not CFb.legend_stage and not CFb.raid_world then
local DFb=U.list(CFb.levels)
local EFb=DFb[#DFb]
if EFb and not W.done(wFb,EFb.id,bbf[1557])then
xFb,yFb,zFb=BFb,DFb[1],EFb
break
end
end
end
if not(xFb and vFb[xFb]and yFb and zFb)then
return
end
if W.open(zFb.id)or not W.open(yFb.id)then
return
end
P.worldSkip=type(P.worldSkip)==bbf[2635]and P.worldSkip or{}
local FFb=P.worldSkip[xFb]
if type(FFb)==bbf[2635]and(FFb.done or os.time()-(tonumber(FFb.at)or 0)<ab.WORLD_SKIP_RETRY)then
return
end
local GFb=N.Worlds[xFb]
local HFb=tostring(GFb and GFb.name or xFb)
local IFb={key=bbf[3388]..zFb.id..bbf[3496],kind=bbf[2683],first=true,level=zFb.id,diff=bbf[1557],label=W.levelName(zFb.id)..bbf[3497]}
local JFb,KFb=pcall(gb.plan,IFb,false)
if not(JFb and type(KFb)==bbf[2635])then
return
end
if not KFb.won then
if ab.every(bbf[4218]..xFb,3600)then
F.log(1,bbf[3293],string.format(bbf[4219],HFb,W.levelName(zFb.id),tostring(KFb.margin)))
end
return
end
local LFb={}
for MFb,NFb in ipairs(U.list(GFb.levels))do
LFb[NFb.id]=W.done(wFb,NFb.id,bbf[1557])
end
local OFb=U.now()
F.log(1,bbf[3293],string.format(bbf[4220],HFb,W.levelName(zFb.id),tostring(KFb.margin)))
local PFb,QFb=F.request(bbf[4221],bbf[4222],xFb)
