task.wait(1)
if W.open(zFb.id)then
RFb=true
break
end
end
local SFb=F.gameSaid(OFb)
P.worldSkip[xFb]={at=os.time(),done=RFb or nil,last=zFb.id,said=SFb and tostring(SFb):sub(1,80)or nil}
F.saveSoon()
if RFb then
local TFb=(N.prof()or{}).level_data or{}
local UFb={}
for VFb,WFb in ipairs(U.list(GFb.levels))do
if WFb.id~=zFb.id and not LFb[WFb.id]and W.done(TFb,WFb.id,bbf[1557])then
table.insert(UFb,W.levelName(WFb.id))
end
end
F.log(1,bbf[3293],string.format(bbf[4223],HFb,#UFb>0 and(bbf[4224]..table.concat(UFb,bbf[2759]))or bbf[4225],SFb and(bbf[4226]..tostring(SFb))or bbf[1551]))
W.lastScored=nil
else
F.log(1,bbf[3293],string.format(bbf[4227],HFb,tostring(SFb or(PFb and QFb)or bbf[3208])))
end
