ab.MM_MIN_SHARE,ab.MM_REST=0.05,3600
function ab.mmShareRecord(VGb)
if not VGb or bb.trialId then
return
end
local WGb= #game:GetService(bbf[1530]):GetPlayers()>1 or bb.withOthers
local XGb=tonumber(bb.enemyHpSum)or 0
if not WGb or XGb<=0 then
