end
local YGb,ZGb=pcall(ab.partyOnly)
if YGb and ZGb then
return
end
local _Gb,aHb,bHb=pcall(bb.damageShares)
local cHb=_Gb and tonumber(bHb)or 0
local dHb=math.min(1,cHb/XGb)
bb.mmShareNow=dHb
P.mmShare=type(P.mmShare)==bbf[2635]and P.mmShare or{}
P.mmShare[VGb]={share=dHb,at=os.time(),wave=bb.wave(),players= #game:GetService(bbf[1530]):GetPlayers()}
if dHb<ab.MM_MIN_SHARE and O.mmGuard==false then
F.log(1,bbf[3339],string.format(bbf[4270],dHb*100,math.floor(ab.MM_MIN_SHARE*100+0.5)))
elseif dHb<ab.MM_MIN_SHARE then
F.log(1,bbf[3339],string.format(bbf[4271],dHb*100,math.floor(ab.MM_MIN_SHARE*100+0.5)))
else
F.log(2,bbf[3339],string.format(bbf[4272],dHb*100))
end
F.saveSoon()
end
function ab.mmTooWeak(eHb)
