end
for hHb,iHb in pairs(P.mmShare)do
local jHb=type(iHb)==bbf[2635]and(tonumber(iHb.share)or 1)<ab.MM_MIN_SHARE and ab.MM_REST-(os.time()-(tonumber(iHb.at)or 0))or 0
if jHb>0 then
local kHb,lHb=pcall(nb.keyName,hHb)
table.insert(gHb,string.format(bbf[4273],kHb and lHb or tostring(hHb),ab.leftWords(jHb),(tonumber(iHb.share)or 0)*100))
end
end
table.sort(gHb)
return gHb
end
function ab.matchSwitch(mHb)
