gb.STYLE_RUNS=20
function gb.styleP(foc,goc)
local hoc=tonumber(foc and foc.p)or 0
if hoc<0.5 then
return hoc
end
goc=goc or((foc.zone or foc.style==bbf[4574])and bbf[4574]or bbf[4639])
local ioc,joc=pcall(db.hiveStyle,goc)
