function gb.objective(Ypc)
if Ypc.kscore then
return(tonumber(Ypc.kills)or 0)+Ypc.wave*0.01
end
return(Ypc.won and 1000 or 0)+Ypc.wave*10-(Ypc.won and Ypc.t/60 or((Ypc.left or 1)*9-math.min(9,Ypc.t/60)))
end
gb.LADDER={1,1.3,1.7,2.2,3,4,6,8,12,16,24}
function gb.cliff(Zpc,_pc,aqc)
local bqc
for cqc,dqc in ipairs(gb.LADDER)do
