if not bqc.won then
return dqc,bqc
end
end
return gb.LADDER[#gb.LADDER],bqc
end
gb.TEAM_FASTER,gb.TEAM_FASTER_S=0.05,15
function gb.teamFaster(eqc,fqc,gqc)
if eqc.infinite or eqc.timeLimit or type(gqc)~=bbf[2635]or not gqc.won or not tonumber(gqc.minutes)then
return nil
end
local hqc=gb.teamFrom(fqc,eqc.map)
