return nil
end
local jqc=gb.run(eqc,hqc,{hpMul=1.3})
if not(jqc and jqc.won)then
return nil
end
local kqc,lqc=tonumber(gqc.minutes)*60,tonumber(iqc.t)or math.huge
if lqc<=kqc*(1-gb.TEAM_FASTER)and kqc-lqc>=gb.TEAM_FASTER_S then
return{mine=kqc,pick=lqc}
end
return nil
end
function gb.exam(mqc,nqc)
local oqc,pqc,qqc=gb.teamFrom(nqc,mqc.map),0,0
for rqc,sqc in ipairs(gb.LADDER)do
local tqc,uqc=0,0
for vqc,wqc in ipairs({0.92,1,1.08})do
local xqc=gb.run(mqc,oqc,{hpMul=sqc*wqc})
if xqc.won then
tqc=tqc+1
end
uqc=uqc+xqc.wave
end
pqc,qqc=pqc+tqc,uqc/3
task.wait()
if tqc==0 then
break
end
end
return pqc,qqc
end
gb.ZONE_CLOSE,gb.ZONE_GAIN=1.3,20
