end
function gb.zoneChoice(zqc,Aqc,Bqc,Cqc)
if O.killZone==false or zqc.zone or bb.forcedWay(zqc)or(zqc.infinite and gb.unbound(zqc.ld))then
return false
end
local Dqc=P.zoneRec[gb.zoneKey(zqc)]
local Eqc=Dqc and(Dqc.style==bbf[4574]or(Dqc.style==nil and Dqc.zone==true))
if Dqc and Dqc.won then
return Eqc==true,Eqc and bbf[4641]or nil
end
if Dqc and Eqc then
return false,bbf[4642]
end
local Fqc=P.modes[zqc.key]
local Gqc=Fqc and tonumber(Fqc.streak)or 0
if not Dqc and Fqc and(tonumber(Fqc.wins)or 0)>0 and Gqc==0 and zqc.key~=bbf[3385]and zqc.key~=bbf[3381]then
return false
end
local Hqc=Dqc~=nil or Gqc>0
local Iqc=Cqc and Bqc<=1 or(not Cqc and Bqc<=gb.ZONE_CLOSE)
if not(Hqc or Iqc)then
return false
end
local Jqc=table.clone(zqc)
Jqc.zone=true
local function Kqc(Lqc)
local Mqc=0
for Nqc,Oqc in ipairs({0.92,1,1.08})do
Mqc=Mqc+gb.objective(gb.run(Lqc,Aqc,{hpMul=Bqc*Oqc}))
end
return Mqc/3
end
local Pqc=Kqc(Jqc)-Kqc(zqc)
if Hqc and Pqc> -gb.ZONE_GAIN then
return true,bbf[4643],Pqc
end
if Iqc and Pqc>gb.ZONE_GAIN then
return true,string.format(bbf[4644],Bqc),Pqc
end
return false,nil,Pqc
end
function gb.strength(Qqc,Rqc)
