local crc=gb.run(Qqc,Sqc,{hpMul=Yqc*brc})
if crc.won then
Zqc=Zqc+1
end
_qc=_qc+crc.wave
end
Tqc,Wqc=Tqc+Zqc,_qc/3
if Yqc==1 then
Uqc,Vqc=Zqc,_qc/3
end
task.wait()
if Zqc==0 then
break
end
end
return Tqc,Uqc,Vqc,Wqc
