if hrc and irc then
erc[irc]=true
end
end
local jrc,krc=pcall(gb.weakPicks,drc)
if jrc and type(krc)==bbf[2635]then
for lrc,mrc in ipairs(krc)do
erc[mrc]=true
end
end
if type(drc)==bbf[2635]and(tonumber(drc.regen)or 0)>0 and(tonumber(drc.shield)or 0)<=0 then
local nrc,orc=pcall(V.bestBleeder)
if nrc and type(orc)==bbf[2635]and orc.unit_id then
local prc=tonumber(V.bleeds(orc.unit_id))or 0
local qrc=false
for rrc in pairs(erc)do
