function gb.weakPicks(vrc)
local wrc=type(vrc)==bbf[2635]and vrc.mod or nil
if not(type(wrc)==bbf[2635]and type(wrc.weak)==bbf[2635])then
return{}
end
local xrc={}
for yrc,zrc in pairs(wrc.weak)do
if(tonumber(zrc)or 0)>=W.WEAK_BIG then
xrc[yrc]=tonumber(zrc)
end
end
if next(xrc)==nil then
return{}
end
local Arc=N.session()
local Brc,Crc={},{}
local Drc=0
local Erc=(tonumber(vrc.regen)or 0)>0
for Frc,Grc in pairs(Arc.profile_data.collection.owned_units)do
local Hrc=Grc.unit_id
if N.Units[Hrc]and not V.isFarm(Hrc)and not V.allyBuff(Hrc)and V.rows(Hrc)and not V.hidden(Hrc)then
local Irc=Arc.collection:get_unit_by_uuid(Grc.uuid)or Grc
local Jrc,Krc=pcall(N.USC.calculate_level,Hrc,tonumber(Irc.xp)or 0)
if Jrc and(tonumber(Krc)or 0)>=gb.GROWN_LEVEL then
local Lrc=V.types(Hrc)
local Mrc,Nrc=pcall(V.dps,Irc,V.rows(Hrc).max,nil)
local Orc=(Mrc and tonumber(Nrc)or 0)/math.max(0.01,tonumber(V.nudge(Hrc))or 1)
if Orc>Drc then
Drc=Orc
end
for Prc in pairs(Lrc)do
if xrc[Prc]then
local Qrc=Orc*xrc[Prc]
if not Brc[Prc]or Qrc>Brc[Prc].v then
Brc[Prc]={id=Hrc,v=Qrc,k=xrc[Prc]}
end
if Erc and V.bleeds(Hrc)==0 and(not Crc[Prc]or Qrc>Crc[Prc].v)then
Crc[Prc]={id=Hrc,v=Qrc,k=xrc[Prc]}
