local Yrc=Xrc and Xrc.v>0 and Wrc.v/Xrc.v or 0
if Yrc>=0.5 and(not Urc or Yrc>Urc)then
Trc,Urc=Vrc,Yrc
end
end
if not Trc then
return Rrc
end
local Zrc={}
for _rc,asc in pairs(Rrc)do
Zrc[_rc]=asc
end
Zrc[Trc]=Src[Trc]
