for gsc,hsc in pairs(type(bsc)==bbf[2635]and bsc or{})do
table.insert(dsc,hsc)
fsc=math.max(fsc,tonumber(hsc.v)or 0)
end
table.sort(dsc,function(isc,jsc)
local ksc,lsc=tonumber(isc.k)or 0,tonumber(jsc.k)or 0
if ksc~=lsc then
return ksc>lsc
end
return isc.v>jsc.v
end)
local msc={}
for nsc,osc in ipairs(dsc)do
if not esc[osc.id]and#msc<3 and osc.v>=fsc*0.1 and osc.v>=(tonumber(csc)or 0)*0.5 then
esc[osc.id]=true
table.insert(msc,osc.id)
end
end
