function gb.lockTeam(Isc,Jsc,Ksc)
local Lsc=table.clone(Isc)
local Msc={}
for Nsc,Osc in ipairs(Lsc)do
Msc[Osc.unit_id]=true
end
local Psc=N.session()
for Qsc in pairs(Ksc)do
if not Msc[Qsc]then
local Rsc
for Ssc,Tsc in ipairs({Jsc or{},(type(Jsc)==bbf[2635]and Jsc.rest)or{}})do
for Usc,Vsc in ipairs(Tsc)do
if Vsc.unit_id==Qsc then
Rsc=Vsc
break
end
end
if Rsc then
break
end
end
if not Rsc and Psc then
local Wsc
for Xsc,Ysc in pairs(Psc.profile_data.collection.owned_units)do
if Ysc.unit_id==Qsc then
local Zsc=Psc.collection:get_unit_by_uuid(Ysc.uuid)or Ysc
local _sc,atc=pcall(V.score,Zsc)
atc=_sc and tonumber(atc)or 0
if not Wsc or atc>Wsc then
Rsc,Wsc=Zsc,atc
end
end
end
end
if Rsc then
local btc
for ctc,dtc in ipairs(Lsc)do
if not Ksc[dtc.unit_id]and V.sameGroup(dtc.unit_id,Qsc)then
btc=ctc
end
end
if not btc and#Lsc<6 then
table.insert(Lsc,Rsc)
else
if not btc then
local etc=0
for ftc,gtc in ipairs(Lsc)do
if V.isFarm(gtc.unit_id)then
etc=etc+1
end
end
local htc
for itc,jtc in ipairs(Lsc)do
if not Ksc[jtc.unit_id]and not(V.isFarm(jtc.unit_id)and etc<=1)then
local ktc,ltc=pcall(V.score,jtc)
ltc=V.isFarm(jtc.unit_id)and math.huge or(ktc and tonumber(ltc)or 0)
if not htc or ltc<htc then
btc,htc=itc,ltc
end
end
end
end
if btc then
Lsc[btc]=Rsc
end
end
Msc[Qsc]=true
end
end
end
return Lsc
end
function gb.bestTeam(mtc,ntc,otc,ptc)
local qtc=U.now()
ptc=ptc or 25
local rtc=table.clone(ntc)
local stc=gb.lockIds(mtc)
if next(stc)then
local ttc,utc=pcall(gb.lockTeam,rtc,otc,stc)
if ttc and type(utc)==bbf[2635]then
rtc=utc
end
end
local function vtc(wtc)
return wtc~=nil and stc[wtc.unit_id]==true
end
local xtc,ytc=gb.cliff(mtc,gb.teamFrom(rtc,mtc.map))
local function ztc(Atc)
local Btc=0
for Ctc,Dtc in ipairs(Atc)do
if V.isFarm(Dtc.unit_id)then
Btc=Btc+1
end
end
return Btc
end
local Etc=ztc(otc)>0
local function Ftc(Gtc)
local Htc=0
for Itc,Jtc in ipairs(Gtc)do
if not V.isFarm(Jtc.unit_id)and not V.allyBuff(Jtc.unit_id)then
Htc=Htc+V.cap(Jtc)
end
end
return Htc
end
local Ktc
while#rtc<6 do
local Ltc,Mtc
local Ntc=Etc and ztc(rtc)==0
for Otc,Ptc in ipairs(otc)do
local Qtc=false
for Rtc,Stc in ipairs(rtc)do
if V.sameGroup(Stc.unit_id,Ptc.unit_id)then
Qtc=true
end
end
if not Qtc and(not Ntc or V.isFarm(Ptc.unit_id))then
local Ttc=table.clone(rtc)
table.insert(Ttc,Ptc)
local Utc=gb.run(mtc,gb.teamFrom(Ttc,mtc.map),{hpMul=xtc})
local Vtc=gb.objective(Utc)
if not Mtc or Vtc>Mtc then
Ltc,Mtc,Ktc=Ptc,Vtc,Utc
end
end
end
if not Ltc then
break
end
table.insert(rtc,Ltc)
end
if Etc and ztc(rtc)==0 then
local Wtc,Xtc
for Ytc=1,#rtc do
for Ztc,_tc in ipairs(vtc(rtc[Ytc])and{}or otc)do
if V.isFarm(_tc.unit_id)then
local auc=table.clone(rtc)
auc[Ytc]=_tc
local buc=gb.run(mtc,gb.teamFrom(auc,mtc.map),{hpMul=xtc})
local cuc=gb.objective(buc)
if not Xtc or cuc>Xtc then
Wtc,Xtc,Ktc=auc,cuc,buc
end
end
end
end
if Wtc then
rtc=Wtc
end
end
local function duc(euc,fuc)
local guc=gb.teamFrom(euc,mtc.map)
return(gb.objective(fuc)+gb.objective(gb.run(mtc,guc,{hpMul=xtc*0.92}))+gb.objective(gb.run(mtc,guc,{hpMul=xtc*1.08})))/3
end
local huc,iuc=Ktc or ytc,duc(rtc,Ktc or ytc)
if type(otc.rest)==bbf[2635]and#otc.rest>0 then
local juc,kuc
for luc,muc in ipairs(rtc)do
if not V.isFarm(muc.unit_id)and not V.allyBuff(muc.unit_id)and not vtc(muc)then
local nuc,ouc=pcall(V.score,muc,mtc.mod)
ouc=(nuc and ouc or 0)*V.skinMul(muc,mtc.skinSet)*V.eventMul(muc,mtc.ld)
if not kuc or ouc<kuc then
juc,kuc=luc,ouc
end
end
end
if juc then
local puc,quc={},U.now()
for ruc,suc in ipairs(otc.rest)do
if U.now()-quc>5 then
break
end
local tuc=false
for uuc,vuc in ipairs(rtc)do
if V.sameGroup(vuc.unit_id,suc.unit_id)then
tuc=true
end
end
if not tuc then
local wuc=table.clone(rtc)
wuc[juc]=suc
table.insert(puc,{u=suc,o=gb.objective(gb.run(mtc,gb.teamFrom(wuc,mtc.map),{hpMul=xtc}))})
end
end
table.sort(puc,function(xuc,yuc)
return xuc.o>yuc.o
end)
otc=table.clone(otc)
for zuc=1,math.min(4,#puc)do
table.insert(otc,1,puc[zuc].u)
end
qtc=qtc+(U.now()-quc)
end
end
for Auc=1,2 do
local Buc=false
for Cuc=1,#rtc do
for Duc,Euc in ipairs(vtc(rtc[Cuc])and{}or otc)do
if U.now()-qtc>ptc then
return rtc,huc,xtc,ytc
end
local Fuc=false
for Guc,Huc in ipairs(rtc)do
if Guc~=Cuc and V.sameGroup(Huc.unit_id,Euc.unit_id)then
Fuc=true
end
end
if rtc[Cuc]and rtc[Cuc].unit_id==Euc.unit_id then
Fuc=true
end
if not Fuc then
local Iuc=table.clone(rtc)
Iuc[Cuc]=Euc
if(not Etc or ztc(Iuc)>0)and Ftc(Iuc)>=math.min(8,Ftc(rtc))then
local Juc=gb.run(mtc,gb.teamFrom(Iuc,mtc.map),{hpMul=xtc})
local Kuc=gb.objective(Juc)
if Kuc>iuc+1 then
Kuc=duc(Iuc,Juc)
if Kuc>iuc+1 then
rtc,iuc,huc,Buc=Iuc,Kuc,Juc,true
end
end
end
end
end
end
if not Buc then
break
end
end
return rtc,huc,xtc,ytc
end
