for UNc=0,TNc-1 do
local VNc=QNc:Lerp(RNc,UNc/TNc)
table.insert(bb.samples,{pos=VNc,prog=(ONc+SNc*UNc/TNc)/math.max(1,MNc),lane=HNc.Name})
end
ONc=ONc+SNc
end
if JNc[#JNc]then
table.insert(bb.samples,{pos=JNc[#JNc],prog=1,lane=HNc.Name})
end
end
end
pcall(bb.readHidden,GNc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local WNc=tonumber(bb.ld and bb.ld._portal_lanes)
local XNc=gb.laneList(bb.samples)
if WNc and WNc>=1 and XNc and#XNc>WNc then
bb.laneWant=WNc
end
bb.laneTotal=XNc and#XNc or 1
bb.countLanes()
