function bb.readHidden(YNc)
local ZNc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(ZNc)~=bbf[2635]or not next(ZNc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local _Nc
for aOc,bOc in pairs(YNc)do
if ZNc[aOc.Name]and type(bOc.points)==bbf[2635]and#bOc.points>=2 then
local cOc={}
for dOc,eOc in ipairs(bOc.points)do
cOc[dOc]=U.flat(eOc.part.Position)
end
local fOc={}
for gOc,hOc in ipairs(bb.samples)do
local iOc=tostring(hOc.lane)
fOc[iOc]=fOc[iOc]or{}
table.insert(fOc[iOc],hOc)
end
local jOc,kOc
for lOc,mOc in pairs(fOc)do
local nOc=0
for oOc=1,#cOc,math.max(1,math.floor(#cOc/20))do
local pOc=math.huge
for qOc,rOc in ipairs(mOc)do
local sOc=(U.flat(rOc.pos)-cOc[oOc]).Magnitude
if sOc<pOc then
pOc=sOc
end
end
nOc=nOc+pOc
end
if not kOc or nOc<kOc then
jOc,kOc=lOc,nOc
end
end
local tOc,uOc,vOc,wOc,xOc,yOc={},nil,nil,nil,0,0
for zOc,AOc in ipairs(cOc)do
local BOc,COc=nil,math.huge
for DOc,EOc in ipairs(fOc[jOc])do
local FOc=(U.flat(EOc.pos)-AOc).Magnitude
if FOc<COc then
COc,BOc=FOc,EOc.prog
end
end
yOc=math.max(yOc,COc)
if vOc then
local GOc=BOc-vOc
local HOc=(GOc>0.002 and 1)or(GOc< -0.002 and-1)or wOc
if wOc and HOc and HOc~=wOc then
table.insert(tOc,math.floor(vOc*1000+0.5)/1000)
end
wOc,xOc=HOc or wOc,xOc+math.abs(GOc)
else
uOc=BOc
end
vOc=BOc
if zOc%50==0 then
task.wait()
end
end
if vOc and yOc<=8 then
table.insert(tOc,math.floor(vOc*1000+0.5)/1000)
_Nc=_Nc or{}
_Nc[aOc.Name]={from=math.floor((uOc or 0)*1000+0.5)/1000,len=math.floor(xOc*1000+0.5)/1000,turns=tOc,road=jOc}
end
end
end
if not _Nc then
return
end
local IOc=bb.ld.map
P.maps[IOc]=P.maps[IOc]or{}
local JOc=P.maps[IOc].hidden
P.maps[IOc].hidden=_Nc
if type(JOc)~=bbf[2635]then
for KOc,LOc in pairs(_Nc)do
F.log(1,bbf[3339],string.format(bbf[4965],KOc,LOc.len,tostring(LOc.road),math.floor((#LOc.turns-1)/2)))
end
F.saveSoon()
end
end
function bb.countLanes()
local MOc,NOc,OOc={},0,0
for POc,QOc in ipairs(bb.samples)do
local ROc=tostring(QOc.lane)
if not MOc[ROc]then
NOc=NOc+1
end
MOc[ROc]=(MOc[ROc]or 0)+1
OOc=OOc+1
end
bb.laneCount={n=NOc,by=MOc,avg=NOc>0 and OOc/NOc or 1}
