bb.LANE_WAIT=3
function bb.portalLanes()
if not bb.laneWant or bb.laneCut then
return true
end
if bb.planning then
return false
end
local VOc,WOc={},0
for XOc,YOc in ipairs(workspace._UNITS:GetChildren())do
local ZOc=YOc:FindFirstChild(bbf[2707])
if ZOc and ZOc:FindFirstChild(bbf[4966])and ZOc.player.Value==nil and ZOc:FindFirstChild(bbf[4967])and YOc:FindFirstChild(bbf[4030])then
local _Oc=tostring(ZOc.lane.Value)
if not VOc[_Oc]then
VOc[_Oc]=true
WOc=WOc+1
end
end
end
if WOc==0 then
if U.now()-(bb.startT or U.now())>45 then
