end
F.log(1,bbf[3339],string.format(bbf[4970],bb.laneWant,bb.laneCut))
if bb.info and O.simSpots and not bb.joinedMid and not bb.random and not bb.infinite and not bb.trialId then
bb.planning=U.now()
task.spawn(function()
local hPc,iPc=pcall(bb.planSpots)
bb.planning=nil
if not hPc then
