end
end)
end
return true
end
function bb.buildWaves()
local jPc=bb.ld
local kPc=jPc and jPc._dungeon and type(jPc._override_waves)==bbf[2635]and jPc._override_waves or nil
local lPc=jPc and N.Waves[(kPc and kPc.template)or jPc.waves or jPc.id]
local mPc
if type(lPc)==bbf[2635]then
mPc=lPc.override_waves or lPc.waves
if not mPc and lPc.template and N.Waves[lPc.template]then
mPc=N.Waves[lPc.template].waves or N.Waves[lPc.template].override_waves
end
end
bb.waveList=U.list(mPc)
bb.infinite=jPc and(jPc._gamemode==bbf[2660]or jPc.infinite)and gb.unbound(jPc)or false
if bb.infinite then
bb.waveList={}
bb.total=math.max(30,math.floor(W.infReach(bb.key)+0.5))
