bb.infWaveAt[nPc]=bb.infWaveAt[nPc]or U.now()
bb.infExtend()
local oPc=math.floor(tonumber(O.infLeaveWave)or 0)
if oPc>0 and nPc>=oPc and not bb.stopping and ab.partyRole()~=bbf[4387]and bb.kind~=bbf[3107]then
bb.stopping=true
F.log(1,bbf[3339],string.format(bbf[4972],nPc))
local pPc,qPc=pcall(bb.sellAll)
if not pPc then
