end
local wPc=N.prof()
local xPc=wPc and wPc.daily_infinite_reward_claims and wPc.daily_infinite_reward_claims[bb.ld.id]
local yPc=type(xPc)==bbf[2635]and(tonumber(xPc.highest_claimed_wave)or 0)>=vPc and os.time()-(tonumber(xPc.highest_claim_time)or 0)<900
if yPc then
