end
local EPc=W.rec(bb.key)
local FPc=tonumber(EPc.timed)or 0
local GPc=W.INF_PAY
local HPc
if zPc>=(GPc.cap+GPc.less)/GPc.per then
HPc=0
else
local IPc=bb.infWaveAt or{}
local JPc,KPc=IPc[zPc],IPc[zPc-5]
if JPc and KPc and JPc>KPc then
