MPc=OPc
end
end
if not MPc or(MPc.score or 0)<=HPc then
return
end
bb.stopping=true
F.log(1,bbf[3339],string.format(bbf[4980],zPc,HPc,MPc.score,MPc.label))
bb.sellAll()
