function bb.valid(jSc,kSc,lSc)
local mSc=N.PC.raycast(jSc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not mSc then
return nil
end
if not N.PC.is_valid_raycast_hit(mSc.Instance,kSc)then
return nil
end
local nSc=mSc.Position
if bb.blockedSpot(nSc)then
return nil
end
local oSc=(tonumber(kSc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(oSc*2,2.5,oSc*2)
bb.probe.CFrame=CFrame.new(nSc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
local pSc=U.flat(nSc)
local qSc=bb.grifZone
if qSc and type(kSc)==bbf[2635]and kSc.id~=V.GRIF.egg and not V.sacFodder(kSc.id)and(pSc-qSc.p).Magnitude<=qSc.r+1.5 then
return nil
end
for rSc,sSc in ipairs(bb.mine or{})do
local tSc=sSc:FindFirstChild(bbf[5003])
local uSc=tSc and tSc.Position or sSc:GetPivot().Position
local vSc=tSc and math.max(tSc.Size.X,tSc.Size.Z)/2 or 1.5
if(pSc-U.flat(uSc)).Magnitude<oSc+vSc then
return nil
end
end
if not lSc then
for wSc,xSc in ipairs(bb.blockers())do
if(pSc-xSc.p).Magnitude<oSc+xSc.r then
return nil
end
end
end
return nSc
end
function bb.buildCandidates()
bb.cands={}
local ySc={}
for zSc=1,#bb.samples,3 do
local ASc=bb.samples[zSc]
local BSc=bb.samples[math.min(#bb.samples,zSc+1)]
local CSc=U.flat(BSc.pos-ASc.pos)
if CSc.Magnitude<0.01 then
CSc=Vector3 .new(1,0,0)
end
CSc=CSc.Unit
local DSc=Vector3 .new(-CSc.Z,0,CSc.X)
for ESc,FSc in ipairs({3,4.5,6,8,10.5,13.5,17})do
for GSc,HSc in ipairs({1,-1})do
local ISc=ASc.pos+DSc*FSc*HSc
local JSc=string.format(bbf[5000],math.floor(ISc.X/1.5),math.floor(ISc.Z/1.5))
if not ySc[JSc]then
ySc[JSc]=true
table.insert(bb.cands,ISc)
end
end
end
end
end
function bb.coverage(KSc,LSc)
local MSc={}
for NSc,OSc in ipairs(KSc)do
local PSc=OSc._stats
if not V.isFarm(PSc.id.Value)and PSc:FindFirstChild(bbf[2905])then
table.insert(MSc,{p=U.flat(OSc:GetPivot().Position),r=PSc.range.Value*(V.SUMMONER[PSc.id.Value]and V.SUMMONER[PSc.id.Value].reach or 1),air=bb.canAir(OSc)})
end
end
local QSc,RSc=0,0
if#MSc>0 then
for SSc,TSc in ipairs(bb.samples)do
if TSc.prog>RSc then
local USc=U.flat(TSc.pos)
for VSc,WSc in ipairs(MSc)do
if(USc-WSc.p).Magnitude<=WSc.r then
if TSc.prog>QSc then
QSc=TSc.prog
end
if WSc.air then
RSc=TSc.prog
break
end
end
end
end
end
end
local XSc,YSc={},bb.laneCount
if YSc and YSc.n>=2 and#MSc>0 then
local ZSc={}
for _Sc,aTc in ipairs(bb.samples)do
local bTc=U.flat(aTc.pos)
for cTc,dTc in ipairs(MSc)do
if(bTc-dTc.p).Magnitude<=dTc.r then
local eTc=tostring(aTc.lane)
ZSc[eTc]=(ZSc[eTc]or 0)+1
if aTc.prog>(XSc[eTc]or 0)then
XSc[eTc]=aTc.prog
end
break
end
end
end
local fTc,gTc={},0
for hTc,iTc in pairs(YSc.by)do
fTc[hTc]=(ZSc[hTc]or 0)/math.max(1,iTc)
gTc=math.max(gTc,fTc[hTc])
end
bb.laneW={}
for jTc,kTc in pairs(YSc.by)do
bb.laneW[jTc]=(YSc.avg/math.max(1,kTc))*(1+1.5*(gTc>0 and(1-fTc[jTc]/gTc)or 0))
end
bb.laneFrac=fTc
else
bb.laneW,bb.laneFrac=nil,nil
end
local lTc,mTc,nTc
if#MSc>0 then
for oTc,pTc in ipairs(LSc)do
local qTc=(bb.laneW and pTc.lane)and(XSc[tostring(pTc.lane)]or 0)or QSc
if pTc.hp>0 and pTc.prog>qTc+0.02 and pTc.prog>(lTc or 0)then
lTc,nTc=pTc.prog,bb.laneW and pTc.lane or nil
end
if pTc.hp>0 and pTc.fly and pTc.prog>RSc+0.02 then
mTc=true
end
end
end
local rTc= #MSc>0 and(bb.pressure or 0)>=QSc-0.08
local sTc
if#MSc>0 and bb.killZone()then
local tTc= #MSc
for uTc,vTc in ipairs(MSc)do
tTc=tTc+vTc.r+vTc.p.X*0.01+vTc.p.Z*0.001
end
if bb._boxSig~=tTc then
local wTc={}
for xTc,yTc in ipairs(bb.samples)do
local zTc,ATc=U.flat(yTc.pos),0
for BTc,CTc in ipairs(MSc)do
if(zTc-CTc.p).Magnitude<=CTc.r then
ATc=ATc+1
end
end
if ATc>0 then
table.insert(wTc,{p=yTc.prog,w=ATc})
end
end
bb._boxSig,bb._boxFrom=tTc,eb.boxFrom(wTc)
end
sTc=bb._boxFrom
end
return{covEnd=QSc,airEnd=RSc,leak=lTc,leakLane=nTc,covL=XSc,airLeak=mTc,push=rTc,units= #MSc,boxFrom=sTc}
end
function bb.needLastLine(DTc)
