local JTc,KTc=U.flat(HTc:GetPivot().Position),ITc.range.Value
for LTc,MTc in ipairs(bb.samples)do
if MTc.prog>=0.85 and(U.flat(MTc.pos)-JTc).Magnitude<=KTc then
