if XTc and N.Attacks[XTc]and N.Attacks[XTc].targets_flying then
VTc=WTc
break
end
end
if VTc==false and bb.cardAir(RTc)then
VTc=0
end
V._airFrom[RTc]=VTc
return VTc or nil
end
function bb.cardAir(YTc)
