function bb.airShare()
local aUc,bUc=0,0
for cUc,dUc in ipairs(bb.mine or{})do
local eUc=dUc._stats.id.Value
if not V.isFarm(eUc)then
local fUc,gUc=pcall(bb.liveDps,dUc,eUc)
gUc=fUc and gUc or 0
aUc=aUc+gUc
if bb.canAir(dUc)then
bUc=bUc+gUc
end
end
end
return aUc>0 and bUc/aUc or 0
