if JUc and KUc and not KUc.unsellable and not bb.sandSold[GUc]and not V.idol(IUc)and HUc:FindFirstChild(bbf[2905])and type(JUc.types)==bbf[2635]and not bb.grifKeep(GUc,IUc)then
