for TUc,UUc in ipairs(bb.mine or{})do
local VUc=UUc:FindFirstChild(bbf[2707])
local WUc=VUc and VUc:FindFirstChild(bbf[3030])and VUc.id.Value
local XUc=WUc and N.Units[WUc]
local YUc=VUc and VUc:FindFirstChild(bbf[3029])and VUc.uuid.Value
if XUc and not XUc.unsellable and not bb.sandSold[WUc]and not V.isFarm(WUc)and not V.allyBuff(WUc)and not V.BLESS.by[WUc]and not V.idol(WUc)and VUc:FindFirstChild(bbf[2905])and not bb.grifKeep(UUc,WUc)then
