end
end
if not cVc then
bb.sandSold[WUc]=true
local fVc=VUc:FindFirstChild(bbf[5009])and tonumber(VUc.total_spent.Value)or 0
local gVc,hVc=F.request(bbf[2836],bbf[2726],UUc)
