local tVc=1
if pVc then
tVc=0.15+0.85*(tonumber(pVc[math.min(gb.BINS,math.floor(sVc.prog*gb.BINS)+1)])or 0)
end
if qVc then
tVc=tVc*(qVc[tostring(sVc.lane)]or 1)
