local IWc=EWc>1 or FWc.won
jb.note(string.format(bbf[5012],IWc and bbf[3444]or(bbf[5013]..FWc.wave)))
if not IWc and O.bailOut~=false then
jb.note(bbf[5014])
elseif not IWc and jb.playLast()then
jb.note(bbf[5015])
