bb.LAYOUT_KEEP,bb.LAYOUT_CONTROL,bb.HIVE_ASIDE,bb.HIVE_LEAD,bb.HIVE_LEAD_MIN=8,2,3600,0.015,300
bb.HIVE_TRY_EVERY,bb.HIVE_TRIALS=3,3
function bb.layoutRecFor(gdd,hdd)
local idd=bb.bookKey(gdd)
P.layoutRec=type(P.layoutRec)==bbf[2635]and P.layoutRec or{}
local jdd=P.layoutRec[idd]
if type(jdd)~=bbf[2635]then
if not hdd then
return nil
end
jdd={at=os.time()}
P.layoutRec[idd]=jdd
if U.count(P.layoutRec)>80 then
local kdd,ldd
for mdd,ndd in pairs(P.layoutRec)do
local odd=type(ndd)==bbf[2635]and tonumber(ndd.at)or 0
if not ldd or odd<ldd then
kdd,ldd=mdd,odd
end
end
P.layoutRec[kdd]=nil
end
end
return jdd
end
function bb.layoutAdd(pdd,qdd,rdd,sdd,tdd)
pdd.runs,pdd.wins=(tonumber(pdd.runs)or 0)+1,(tonumber(pdd.wins)or 0)+(qdd and 1 or 0)
pdd.sec,pdd.wave=type(pdd.sec)==bbf[2635]and pdd.sec or{},type(pdd.wave)==bbf[2635]and pdd.wave or{}
if qdd and tonumber(rdd)then
table.insert(pdd.sec,math.floor(rdd+0.5))
end
table.insert(pdd.wave,tonumber(sdd)or 0)
if tonumber(tdd)then
pdd.kills=type(pdd.kills)==bbf[2635]and pdd.kills or{}
table.insert(pdd.kills,math.floor(tonumber(tdd)))
while#pdd.kills>bb.LAYOUT_KEEP do
table.remove(pdd.kills,1)
end
end
while#pdd.sec>bb.LAYOUT_KEEP do
table.remove(pdd.sec,1)
end
while#pdd.wave>bb.LAYOUT_KEEP do
table.remove(pdd.wave,1)
end
end
function bb.layoutJudge(udd,vdd,wdd,xdd,ydd)
ydd=ydd or bbf[5172]
local zdd,Add=tonumber(udd and udd.runs)or 0,tonumber(vdd and vdd.runs)or 0
if zdd<1 or Add<bb.LAYOUT_CONTROL then
return nil
end
if xdd and type(udd.kills)==bbf[2635]and type(vdd.kills)==bbf[2635]and#udd.kills>=1 and#vdd.kills>=bb.LAYOUT_CONTROL then
local Bdd,Cdd=bb.labMedian(udd.kills),bb.labMedian(vdd.kills)
if Bdd and Cdd and Bdd<Cdd*0.97 and(#udd.kills>=2 or Bdd<Cdd*0.85)then
return string.format(bbf[5173],Bdd,Cdd,ydd)
end
return nil
end
local Ddd,Edd=(tonumber(udd.wins)or 0)/zdd,(tonumber(vdd.wins)or 0)/Add
if not wdd and Edd>=0.5 then
if Ddd+0.25<Edd and(zdd>=2 or(Ddd==0 and Edd>=0.9 and Add>=3))then
return string.format(bbf[5174],tonumber(udd.wins)or 0,zdd,zdd==1 and bbf[1551]or bbf[2479],tonumber(vdd.wins)or 0,Add,ydd)
end
local Fdd,Gdd=bb.labMedian(udd.sec),bb.labMedian(vdd.sec)
if Fdd and Gdd and Fdd>Gdd*1.10 and(#udd.sec>=2 or Fdd>Gdd*1.25)then
return string.format(bbf[5175],math.floor(Fdd/60),Fdd%60,math.floor(Gdd/60),Gdd%60,ydd)
end
return nil
end
local Hdd,Idd=bb.labMedian(udd.wave),bb.labMedian(vdd.wave)
if Hdd and Idd and Hdd<Idd-math.max(1,Idd*0.03)and(zdd>=2 or Hdd<Idd*0.85)then
return string.format(bbf[5176],Hdd,Idd,ydd)
end
return nil
end
function bb.layoutResult(Jdd,Kdd)
local Ldd=bb.info
local Mdd=bb.layoutSrc
if not(Ldd and Mdd)or bb.labTest or bb.withOthers or bb.fastAlways then
return
end
if bb.infinite and not Ldd.timeLimit then
return
end
local Ndd=bb.wave()
local Odd=bb.layoutRecFor(Ldd,true)
Odd.at=os.time()
local Pdd=Ldd.timeLimit~=nil
local Qdd=Ldd.killScore and true or nil
local Rdd=Qdd and(bb.killsEnd or bb.realKills())or nil
if Mdd==bbf[5139]then
local Sdd=bb.bookFor(Ldd)
if not Sdd then
return
end
Sdd.real=type(Sdd.real)==bbf[2635]and Sdd.real or{}
bb.layoutAdd(Sdd.real,Jdd,Kdd,Ndd,Rdd)
local Tdd=Sdd.aside==nil and bb.layoutJudge(Sdd.real,Odd.own,Pdd,Qdd)or nil
if Tdd then
Sdd.aside={at=os.time(),why=Tdd}
F.log(1,bbf[5068],string.format(bbf[5177],Tdd))
end
elseif Mdd==bbf[4469]then
Odd.hiveUnit=type(Odd.hiveUnit)==bbf[2635]and Odd.hiveUnit or{}
local Udd=Odd.hiveUnit
bb.layoutAdd(Udd,Jdd,Kdd,Ndd,Rdd)
local Vdd=bb.bookFor(Ldd)
local Wdd=Vdd and type(Vdd.real)==bbf[2635]and(tonumber(Vdd.real.runs)or 0)>=bb.LAYOUT_CONTROL
local Xdd=Wdd and Vdd.real or Odd.own
local Ydd=bb.layoutJudge(Udd,Xdd,Pdd,Qdd,Wdd and bbf[5178]or nil)
if Ydd then
Udd.aside,Udd.why=os.time(),Ydd
F.log(1,bbf[5068],string.format(bbf[5179],Ydd))
elseif(tonumber(Udd.runs)or 0)>=bb.HIVE_TRIALS then
local Zdd=Xdd and bb.layoutJudge(Xdd,Udd,Pdd,Qdd,bbf[5180])
if Zdd and Vdd and type(bb.hiveUnitPlan)==bbf[2635]then
for _dd,aed in pairs(bb.hiveUnitPlan)do
Vdd.spots[_dd]=aed
end
Vdd.real={runs=Udd.runs,wins=Udd.wins,sec=Udd.sec,wave=Udd.wave,kills=Udd.kills}
Vdd.hive,Vdd.aside=os.time(),nil
Odd.hiveUnit=nil
F.log(1,bbf[5068],string.format(bbf[5181],Zdd))
else
Udd.aside,Udd.why=os.time(),bbf[5182]
F.log(1,bbf[5068],bbf[5183])
end
end
else
Odd[Mdd]=type(Odd[Mdd])==bbf[2635]and Odd[Mdd]or{}
local bed=Odd[Mdd]
bb.layoutAdd(bed,Jdd,Kdd,Ndd,Rdd)
if Mdd==bbf[4468]and bed.aside==nil then
local ced=bb.layoutJudge(bed,Odd.own,Pdd,Qdd)
if ced then
bed.aside,bed.why=os.time(),ced
F.log(1,bbf[5068],string.format(bbf[5184],ced))
end
end
end
F.saveSoon()
end
bb.CONTROL_WORDS={bbf[5185],bbf[5186],bbf[5187],bbf[5188]}
function bb.controlSpot(ded,eed)
if not bb.killZone()then
return nil
end
local ged=gb.holds
if not ged(ded.id)or V.toggleOf(ded.id)then
return nil
end
local hed,ied,jed,ked=1,0,0,{}
local led=bb.hurtSamples()
for med,ned in ipairs(bb.mine or{})do
local oed=ned._stats
local ped=oed.id.Value
if oed:FindFirstChild(bbf[2905])and not V.isFarm(ped)and not V.allyBuff(ped)then
local qed,sed=U.flat(ned:GetPivot().Position),oed.range.Value
if ged(ped)and not V.toggleOf(ped)then
jed=jed+1
table.insert(ked,{p=qed,r=sed})
else
for ted,ued in ipairs(led)do
if(U.flat(ued.pos)-qed).Magnitude<=sed then
hed,ied=math.min(hed,ued.prog),math.max(ied,ued.prog)
end
end
end
end
end
if ied<=hed then
hed,ied=0.75,0.98
end
local ved=(eed or jed)+1
local wed=({hed,ied,(hed+ied)/2,hed-(ied-hed)/2})[ved]
if not wed then
return nil
end
local xed=V.range(ded.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local yed={}
for zed,Aed in ipairs(bb.cands)do
local Bed,Ced,Ded=U.flat(Aed),0,0
for Eed,Fed in ipairs(led)do
if(U.flat(Fed.pos)-Bed).Magnitude<=xed then
Ded=Ded+1
if math.abs(Fed.prog-wed)<=0.05 then
Ced=Ced+1
local Ged=U.flat(Fed.pos)
for Hed,Ied in ipairs(ked)do
if(Ged-Ied.p).Magnitude<=Ied.r then
Ced=Ced-0.5
break
end
end
end
end
end
if Ced>0 then
table.insert(yed,{pos=Aed,sc=Ced,cov=Ded})
end
if zed%60==0 then
task.wait()
end
end
table.sort(yed,function(Jed,Ked)
return Jed.sc>Ked.sc
end)
for Led,Med in ipairs(yed)do
local Ned=bb.valid(Med.pos,ded.data)
if Ned then
F.log(1,bbf[5007],string.format(bbf[5189],V.name(ded.id),bb.CONTROL_WORDS[ved],math.floor(wed*100+0.5)))
return Ned,Med.cov,wed
end
if Led%20==0 then
task.wait()
end
end
return nil
end
function bb.holdSpot(Oed)
local Ped,Qed=gb.holds(Oed.id)
local Red=false
if not Ped and bb.info and(tonumber(bb.info.regen)or 0)>0 then
local Sed,Ted=pcall(V.bleeds,Oed.id)
if Sed and Ted then
Ped,Qed,Red=true,Ted,true
end
end
if not Ped then
return nil
end
if V.killFed(Oed.id)then
return nil
end
local Ued,Ved={},0
for Wed,Xed in ipairs(bb.mine or{})do
local Yed=Xed._stats
local Zed=Yed.id.Value
if Yed:FindFirstChild(bbf[2905])and not V.isFarm(Zed)and not V.allyBuff(Zed)and Zed~=Oed.id then
local _ed,afd=pcall(bb.liveDps,Xed,Zed)
afd=_ed and tonumber(afd)or 0
if afd>0 then
table.insert(Ued,{p=U.flat(Xed:GetPivot().Position),r=Yed.range.Value,d=afd})
Ved=Ved+afd
end
end
end
if#Ued==0 or Ved<=0 then
return nil
end
local bfd=bb.hurtSamples()
local cfd={}
for dfd,efd in ipairs(bfd)do
local ffd,gfd=U.flat(efd.pos),0
for hfd,ifd in ipairs(Ued)do
if(ffd-ifd.p).Magnitude<=ifd.r then
gfd=gfd+ifd.d
end
end
cfd[dfd]=gfd/Ved
end
local jfd=V.range(Oed.u,math.min(tonumber(Qed)or 0,3,V.rows(Oed.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1)
local kfd,lfd,mfd
for nfd,ofd in ipairs(bb.cands)do
local pfd,qfd,rfd=U.flat(ofd),0,0
for sfd,tfd in ipairs(bfd)do
if(U.flat(tfd.pos)-pfd).Magnitude<=jfd then
qfd=qfd+cfd[sfd]
rfd=rfd+1
end
end
if qfd>0 and(not lfd or qfd>lfd)then
local ufd=bb.valid(ofd,Oed.data)
if ufd then
kfd,lfd,mfd=ufd,qfd,rfd
end
end
if nfd%40==0 then
task.wait()
end
end
if not kfd then
return nil
end
bb.holdSaid=bb.holdSaid or{}
if not bb.holdSaid[Oed.id]then
bb.holdSaid[Oed.id]=true
F.log(1,bbf[5007],string.format(Red and bbf[5190]or bbf[5191],V.name(Oed.id)))
end
return kfd,mfd or 0
end
function bb.buffAtSpot(vfd,wfd,xfd)
local yfd={}
for zfd,Afd in ipairs(type(xfd)==bbf[2635]and xfd or{})do
local Bfd=type(Afd.b)==bbf[2635]and type(Afd.b.types)==bbf[2635]and tonumber(Afd.b.types[wfd])or nil
if Bfd and(Afd.pos-vfd).Magnitude<=Afd.range then
local Cfd=yfd[Afd.b.attack]
if not Cfd then
Cfd={n=0,rate=Bfd,b=Afd.b}
yfd[Afd.b.attack]=Cfd
end
Cfd.n=Cfd.n+1
if Afd.cd then
Cfd.cd=math.min(Cfd.cd or math.huge,Afd.cd)
end
end
end
local Dfd=0
for Efd,Ffd in pairs(yfd)do
local Gfd=math.max(1,tonumber(Ffd.b.time)or 30)
local Hfd=math.max(1,Ffd.cd or tonumber(Ffd.b.cd)or 60)
local Ifd=V.stackCap(Efd)
local Jfd
if Ifd then
Jfd=math.min(Ifd,(1+Ffd.rate)^math.floor(Ffd.n*Gfd/Hfd+0.001)-1)
else
Jfd=math.min(Ffd.rate,Ffd.n*Ffd.rate*math.min(1,Gfd/Hfd))
end
Dfd=math.max(Dfd,Jfd)
end
return Dfd
end
function bb.blockSpot(Kfd,Lfd)
if V.isFarm(Kfd.id)or V.allyBuff(Kfd.id)then
return nil
end
local Mfd,Nfd=V.types(Kfd.id)
local Ofd={}
for Pfd,Qfd in ipairs(bb.fieldBuffers())do
if type(Qfd.b.types)==bbf[2635]and Qfd.b.types[Nfd]then
table.insert(Ofd,Qfd)
end
end
if#Ofd==0 then
return nil
end
local Rfd=(bb.info and tonumber(bb.info.rangeScale))or 1
local Sfd=V.range(Kfd.u,V.rows(Kfd.id).max)*Rfd
local Tfd=bb.buffAtSpot(Lfd,Nfd,Ofd)
local Ufd=bb.cover(Lfd,Sfd)
local Vfd,Wfd,Xfd,Yfd=nil,Ufd*(1+Tfd),Tfd,Ufd
local Zfd=0
local _fd=bb.newRadius(Kfd)
for agd,bgd in ipairs(Ofd)do
for cgd,dgd in ipairs(bb.ringSpots(bgd.pos,(bgd.hr or bb.HB_R)+_fd+0.1,bgd.range))do
local egd=bb.valid(dgd,Kfd.data)
Zfd=Zfd+1
if Zfd%40==0 then
task.wait()
end
if egd then
local fgd=bb.buffAtSpot(egd,Nfd,Ofd)
if fgd>Tfd+0.001 then
local ggd=bb.cover(egd,Sfd)
local hgd=ggd*(1+fgd)
if hgd>Wfd then
Vfd,Wfd,Xfd,Yfd=egd,hgd,fgd,ggd
end
end
end
end
end
if not Vfd then
return nil
end
F.log(1,bbf[5007],string.format(bbf[5192],V.name(Kfd.id),math.floor(Xfd*100+0.5),math.floor(Tfd*100+0.5),math.floor(Yfd/math.max(1,Ufd)*100+0.5)))
return Vfd
end
function bb.bestSpot(igd,jgd,kgd)
if(igd._grif or igd.id==V.GRIF.egg)and not kgd and bb.grifOn()then
