Pgd=nil
end
if Pgd and Igd then
local Qgd,Rgd,Sgd=false,U.flat(Pgd),V.range(igd.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local Tgd=bb.depth and bb.depth.leakLane and tostring(bb.depth.leakLane)or nil
for Ugd,Vgd in ipairs(bb.hurtSamples())do
if Vgd.prog>=Igd+0.02 and(not Tgd or tostring(Vgd.lane)==Tgd)and(U.flat(Vgd.pos)-Rgd).Magnitude<=Sgd then
