end
table.insert(Rjd,{s=Ujd,n=Wjd,d=Xjd})
end
if Sjd<1 then
return{}
end
local akd=Sjd>=2
local bkd,ckd={},{}
for dkd,ekd in ipairs(Rjd)do
if(akd and ekd.n>=Sjd*bb.BARR_DENSE)or(not akd and ekd.n>=1)then
local fkd=tostring(ekd.s.lane)
if not bkd[fkd]then
bkd[fkd]={}
