end)
for mkd=2,#jkd do
if(jkd[mkd].s.prog or 0)-(jkd[mkd-1].s.prog or 0)>bb.BARR_GAP then
for nkd= #jkd,mkd,-1 do
table.remove(jkd,nkd)
end
break
end
end
table.sort(jkd,function(okd,pkd)
if okd.d~=pkd.d then
return okd.d<pkd.d
end
return(okd.s.prog or 0)>(pkd.s.prog or 0)
end)
else
table.sort(jkd,function(qkd,rkd)
if qkd.n~=rkd.n then
return qkd.n>rkd.n
end
return(qkd.s.prog or 0)>(rkd.s.prog or 0)
end)
end
gkd=math.max(gkd,#jkd)
end
local skd={}
for tkd=1,gkd do
for ukd,vkd in ipairs(ckd)do
if bkd[vkd][tkd]then
table.insert(skd,bkd[vkd][tkd].s.pos)
end
end
end
return skd
end
