table.insert(Dmd.defs,{slot=Fmd.slot,id=Fmd.id,k=Fmd.k,p=Fmd.p,lane=Fmd.lane,w=Fmd.w,a=Fmd.a,b=Fmd.b,n=Fmd.n,d0=Fmd.d0})
if#Dmd.defs>=12 then
