function bb.defTick()
if not O.defenses or bb.finished or not(bb.ld and(bb.ld._swordsmith or bb.ld._own_defenses))then
return
end
bb.defFail=bb.defFail or{}
bb.defUsed=bb.defUsed or{}
local Gmd={}
for Hmd,Imd in ipairs(bb.mine or{})do
local Jmd=Imd:FindFirstChild(bbf[2707])
if Jmd and Jmd:FindFirstChild(bbf[3030])and Jmd:FindFirstChild(bbf[2905])and not V.isFarm(Jmd.id.Value)then
table.insert(Gmd,{p=U.flat(Imd:GetPivot().Position),r=tonumber(Jmd.range.Value)or 0})
end
end
if#Gmd==0 then
return
end
local Kmd=bb.defList()
local Lmd
do
local Mmd=(bb.info and tonumber(bb.info.rangeScale))or 1
for Nmd,Omd in ipairs(V.equipped())do
if V.allyBuff(Omd.id)and not V.isFarm(Omd.id)then
local Pmd,Qmd=pcall(V.range,Omd.u,0)
if Pmd and tonumber(Qmd)then
Lmd=math.max(Lmd or 0,Qmd*Mmd)
end
end
end
end
if#Kmd==0 and not bb.defWornSaid then
bb.defWornSaid=true
local Rmd,Smd,Tmd=pcall(ab.defWorn)
if Rmd and Smd>0 then
F.log(1,bbf[3736],string.format(bbf[5205],Smd,Smd==1 and bbf[5206]or bbf[5207],Tmd,hb.have(bbf[3722]),O.defRepair and bbf[5208]or bbf[5209]))
end
end
for Umd,Vmd in ipairs(Kmd)do
local Wmd=Vmd.kind==bbf[5199]and#Gmd<bb.BARR_TEAM and bb.wave()<bb.BARR_WAVE
if not Wmd and(bb.defFail[Vmd.slot]or 0)<3 and not(bb.defWait and bb.defWait[Vmd.slot]and#Gmd<=bb.defWait[Vmd.slot])then
local Xmd=bb.defPick(Vmd.kind,Vmd.range,Gmd,bb.cands or{},bb.samples or{},bb.cover,Lmd)
local Ymd
for Zmd,_md in ipairs(Xmd)do
if bb.defTaken(_md,bb.defUsed)then
Ymd=nil
elseif Vmd.kind==bbf[5200]or Vmd.kind==bbf[5199]then
local bnd=N.PC.raycast(_md+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
local cnd,dnd=pcall(N.PC.is_valid_raycast_hit,bnd and bnd.Instance,Vmd.unit)
Ymd=bnd and cnd and dnd and bnd.Position or nil
else
Ymd=bb.valid(_md,Vmd.unit)
end
if Ymd then
break
end
end
if not Ymd then
bb.defWait=bb.defWait or{}
if not bb.defWait[Vmd.slot]then
F.log(1,bbf[3736],string.format(bbf[5210],Vmd.name))
end
bb.defWait[Vmd.slot]= #Gmd
else
local fnd,gnd=F.request(bbf[5211],bbf[4437],Vmd.d.unit_uuid,N.Util.CFramePLV(Ymd,bb.lookAt(Ymd)))
table.insert(bb.defUsed,U.flat(Ymd))
if fnd and gnd then
Vmd.d.placed=true
pcall(bb.defNote,Vmd,Ymd,Gmd)
local hnd=0
for ind,jnd in ipairs(Gmd)do
if(jnd.p-U.flat(Ymd)).Magnitude<=Vmd.range then
hnd=hnd+1
end
end
F.log(1,bbf[3736],string.format(bbf[5212],Vmd.name,bb.spotKey(Ymd),Vmd.kind==bbf[2837]and string.format(bbf[5213],hnd,#Gmd)or(Vmd.kind==bbf[5201]and string.format(bbf[5214],bb.cover(Ymd,Vmd.range))or(Vmd.kind==bbf[5200]and bbf[5215]or bbf[5216]))))
else
bb.defFail[Vmd.slot]=(bb.defFail[Vmd.slot]or 0)+1
if bb.defFail[Vmd.slot]>=3 then
F.log(1,bbf[3736],string.format(bbf[5217],Vmd.name,tostring(gnd)))
end
end
end
return
end
end
end
function bb.unplacedWhy(knd,lnd)
if lnd.farm and not lnd.farmUnits then
return bbf[5218]
end
if(lnd.noSpot or 0)>=3 then
return bbf[5219]
end
if(lnd.noSpot or 0)>=1 then
return string.format(bbf[5220],lnd.noSpot,lnd.noSpot==1 and bbf[1551]or bbf[2479])
end
if lnd.cost>0 and lnd.money<lnd.cost and lnd.cost>lnd.spent*0.5 then
return string.format(bbf[5221],U.fmt(lnd.cost),U.fmt(lnd.money))
end
return string.format(bbf[5222],lnd.wave)
end
function bb.unplacedLine(mnd)
if bb.joinedMid or bb.random or bb.trialId then
return nil
end
local nnd={}
for ond,pnd in ipairs(bb.mine or{})do
local qnd=pnd:FindFirstChild(bbf[2707])
if qnd and qnd:FindFirstChild(bbf[3030])then
nnd[qnd.id.Value]=true
end
end
local rnd={}
for snd,tnd in ipairs(V.equipped())do
if not(bb.placedAt and bb.placedAt[tnd.uuid])and not nnd[tnd.id]then
local und=bb.unplacedWhy(tnd,{farm=V.isFarm(tnd.id),farmUnits=O.farmUnits==true,noSpot=bb.noSpot and bb.noSpot[tnd.uuid]or 0,cost=tonumber(tnd.data and tnd.data.cost)or 0,money=bb.money(),spent=tonumber(bb.spent)or 0,wave=bb.wave()})
table.insert(rnd,string.format(bbf[4823],V.name(tnd.id),und))
end
end
if#rnd==0 then
return nil
end
return string.format(bbf[5223],mnd and bbf[5224]..(#rnd==1 and bbf[4401]or bbf[4402])or bbf[1551],table.concat(rnd,bbf[3028]))
end
function bb.lookAt(vnd)
local wnd,xnd=math.huge,nil
for ynd,znd in ipairs(bb.samples)do
local And=(U.flat(znd.pos)-U.flat(vnd)).Magnitude
if And<wnd then
wnd,xnd=And,znd.pos
end
end
local Bnd=xnd and U.flat(xnd-vnd)or Vector3 .new(0,0,-1)
return Bnd.Magnitude>0.01 and Bnd.Unit or Vector3 .new(0,0,-1)
end
function bb.shieldNote()
if not(bb.info and(tonumber(bb.info.shield)or 0)>0)or bb.random then
return
end
local Cnd,Dnd=pcall(bb.damageShares)
if not(Cnd and type(Dnd)==bbf[2635])then
