bb.placeLog=bb.placeLog or{}
table.insert(bb.placeLog,{t=math.floor(U.now()-(bb.startT or U.now())),w=bb.wave(),id=Vnd.id,x=math.floor(Ynd.X),z=math.floor(Ynd.Z),cover=math.floor((Znd or 0)+0.5),why=tostring(Wnd):sub(1,90)})
F.status(bbf[5071],string.format(bbf[5229],V.name(Vnd.id),Wnd))
bb.placedAt=bb.placedAt or{}
bb.placedAt[Vnd.uuid]=(bb.placedAt[Vnd.uuid]or 0)+1
return true
end
if _nd>=(Vnd.data.cost or 0)and bb.random then
bb.placeFail=bb.placeFail or{}
bb.placeFail[Vnd.uuid]=(bb.placeFail[Vnd.uuid]or 0)+1
if bb.placeFail[Vnd.uuid]>=2 then
bb.noSpot[Vnd.uuid]=3
if bb.noSpotField then
bb.noSpotField[Vnd.uuid]=nil
end
F.log(1,bbf[5007],string.format(bbf[5230],V.name(Vnd.id),bb.fieldCount(),bb.FIELD_MAX))
end
end
if bod and _nd>=(Vnd.data.cost or 0)and not bb.random then
local dod=bb.spotKey(Ynd)
bb.refused[dod]=true
bb.refusals=(bb.refusals or 0)+1
bb.unitRefusals[Vnd.uuid]=(bb.unitRefusals[Vnd.uuid]or 0)+1
if not bb.crowded()then
local eod=bb.mapKey()
P.blocked[eod]=P.blocked[eod]or{}
if not bb.refusedRun[dod]then
P.blocked[eod][dod]=(tonumber(P.blocked[eod][dod])or 0)+1
bb.refusedRun[dod]=true
P.blockedAt[eod]=P.blockedAt[eod]or{}
P.blockedAt[eod][dod]=os.time()
end
if bb.unitRefusals[Vnd.uuid]>=3 then
local fod=math.max(1,bb.count(Vnd.uuid))
if P.caps[Vnd.uuid]~=fod or not V.learnedCap(Vnd.uuid)then
P.caps[Vnd.uuid],P.capsAt[Vnd.uuid]=fod,os.time()
F.log(1,bbf[5007],string.format(bbf[5231],V.name(Vnd.id),fod))
end
end
elseif bb.unitRefusals[Vnd.uuid]>=3 and(bb.noSpot[Vnd.uuid]or 0)<3 then
bb.noSpot[Vnd.uuid]=3
if bb.noSpotField then
bb.noSpotField[Vnd.uuid]=nil
end
F.log(1,bbf[5007],string.format(bbf[5232],V.name(Vnd.id)))
end
if bb.refusals>=bb.REFUSE_FREE then
if not bb.placePause then
F.log(1,bbf[5007],string.format(bbf[5233],bb.refusals,bb.REFUSE_PAUSE))
end
bb.placePause=U.now()+bb.REFUSE_PAUSE
end
F.log(2,bbf[5007],bbf[5234]..dod..bbf[3639]..V.name(Vnd.id))
