if jod then
for kod,lod in ipairs(jod:GetChildren())do
local nod=lod:FindFirstChild(bbf[2707])
if nod and nod:FindFirstChild(bbf[3029])and nod.player.Value==M and nod.uuid.Value==god then
hod=hod+1
end
end
end
end
