end
function bb.measure()
local ood,pod=bb.calRun,bb.info
if not(ood and pod)then
return
end
pcall(bb.sampleHelpers)
local qod=U.now()
local rod=bb.wave()
local sod=bb.money()
if not ood.start and sod>0 and#bb.mine==0 then
ood.start=sod
end
if rod~=ood.lastW then
if bb.trialId and rod>0 then
bb.trialTrace=bb.trialTrace or{}
local tod,uod,vod,wod=0,{},0,0
for xod,yod in ipairs(bb.mine)do
local zod=yod._stats
if zod.id.Value==bb.trialId then
tod=tod+1
table.insert(uod,tostring(zod.upgrade.Value))
elseif not V.isFarm(zod.id.Value)then
wod=wod+1
end
end
pcall(bb.sampleHelpers,true)
for Aod,Bod in pairs(bb.ownDealt)do
if Bod.id==bb.trialId then
vod=vod+Bod.v
end
end
local Cod=0
for Dod,Eod in pairs(bb.helperDealt)do
if Eod.owner==bb.trialId then
Cod=Cod+Eod.v
end
end
table.insert(bb.trialTrace,string.format(bbf[5235],rod,qod-(bb.startT or qod),sod,table.concat(uod,bbf[3358]),wod,vod+Cod,#(bb.enemies or{}),bb.hpAliveRaw or 0,bb.waveMax[rod-1]or 0,bb.teamDps or 0))
end
if ood.lastW and ood.lastW>0 and ood.lastWT then
table.insert(ood.waveSec,qod-ood.lastWT)
end
if ood.paidT and rod>0 and qod-ood.paidT<15 then
table.insert(ood.skip,qod-ood.paidT)
end
ood.paidT=nil
if rod>0 then
ood.alive[tostring(rod)]=bb.hpAliveRaw or 0
end
ood.lastW,ood.lastWT=rod,qod
end
local Fod=workspace:FindFirstChild(bbf[5236])
if Fod and rod>0 then
ood.timer[tostring(rod)]=math.max(ood.timer[tostring(rod)]or 0,tonumber(Fod.Value)or 0)
end
local God=tonumber(bb.spent)or 0
local Hod=sod-(bb.lastMoneyR or sod)+(God-(bb.lastSpentR or God))
bb.lastMoneyR,bb.lastSpentR=sod,God
bb.incomeLog=bb.incomeLog or{}
if Hod>0 then
table.insert(bb.incomeLog,{t=qod,y=Hod})
end
while bb.incomeLog[1]and qod-bb.incomeLog[1].t>30 do
table.remove(bb.incomeLog,1)
end
local Iod=0
for Jod,Kod in ipairs(bb.incomeLog)do
Iod=Iod+Kod.y
end
local Lod=math.min(30,qod-(bb.startT or qod))
bb.incomeRate=Lod>=8 and Iod/Lod or nil
for Mod,Nod in ipairs(bb.enemies)do
local Ood=Nod.m
local Pod=bb.track[Ood]
if not Pod then
local Qod=Ood._stats
local Rod=Ood:FindFirstChildOfClass(bbf[3046])
local Sod=pod.cfgById[Qod.id.Value]
local Tod=Sod and gb.baseStats(pod,Sod)
if Rod and Tod and rod>0 then
local Uod=Tod*pod.hpRaw*gb.waveScale(pod,rod,pod.list[rod])
if Uod>0 and Rod.MaxHealth>0 then
table.insert(ood.hp,Rod.MaxHealth/Uod)
end
end
bb.track[Ood]={t=qod,p=Nod.prog,sp=(Qod:FindFirstChild(bbf[5237])and tonumber(Qod.speed.Value))or 1}
if Rod and Rod.MaxHealth>0 then
bb.enemyHpSum=(bb.enemyHpSum or 0)+Rod.MaxHealth
end
if rod>0 then
ood.spawn[tostring(rod)]=(ood.spawn[tostring(rod)]or 0)+1
ood.spawnLast[tostring(rod)]=qod-(ood.lastWT or qod)
end
elseif not Pod.done and qod-Pod.t>=15 then
Pod.done=true
local Vod=(Nod.prog-Pod.p)/(qod-Pod.t)/math.max(0.1,Pod.sp)
if Vod>0.001 and Nod.prog<0.95 then
table.insert(ood.walk,Vod)
end
end
end
local Wod=0
for Xod,Yod in ipairs(bb.mine)do
local Zod=Yod._stats:FindFirstChild(bbf[3031])
if Zod then
Wod=Wod+Zod.Value
end
end
for _od,apd in pairs(bb.helperDealt or{})do
if apd.owner and V.SUMMONER[apd.owner]and not V.droneHelper(apd)then
Wod=Wod+(tonumber(apd.v)or 0)
end
end
ood.potSum=ood.potSum or 0
if ood.lastDealtT then
local bpd=qod-ood.lastDealtT
local cpd=0
ood.potBy=ood.potBy or{}
ood.potExp=ood.potExp or{}
for dpd,epd in ipairs(bb.mine)do
local fpd=epd._stats
local gpd=fpd.id.Value
if not V.isFarm(gpd)and((fpd:FindFirstChild(bbf[5238])and fpd.target.Value~=nil)or bb.inReach(epd,gpd))then
local hpd,ipd=pcall(bb.liveDps,epd,gpd)
if hpd and ipd then
cpd=cpd+ipd*bpd
local jpd=math.max(0.5,V.nudge(gpd))
local kpd=ipd/jpd
local lpd,mpd=pcall(function()
return V.passive(gpd).mark
end)
if lpd and mpd and fpd:FindFirstChild(bbf[3087])then
kpd=kpd+(tonumber(mpd.dot)or 0)*fpd.damage.Value
end
ood.potBy[gpd]=(ood.potBy[gpd]or 0)+kpd*bpd
ood.potExp[gpd]=(ood.potExp[gpd]or 0)+kpd*jpd*bpd
end
end
end
ood.potWin=(ood.potWin or 0)+cpd
if qod-(ood.winT or qod)>=5 then
local npd=Wod-(ood.winDealt or Wod)
if ood.potWin>0 and npd>=0 then
ood.dealtSum=(ood.dealtSum or 0)+npd
ood.potSum=ood.potSum+ood.potWin
end
ood.winT,ood.winDealt,ood.potWin=qod,Wod,0
end
end
if not ood.winT then
ood.winT,ood.winDealt=qod,Wod
end
ood.lastDealtT=qod
if rod~=ood.dpsW and rod>0 then
ood.dpsAt[tostring(rod)]=bb.teamDps or 0
ood.dpsW=rod
end
local opd=math.min(1,qod-(ood.densT or qod))
ood.densT=qod
for ppd,qpd in ipairs(bb.enemies)do
local rpd=math.min(gb.BINS,math.floor(qpd.prog*gb.BINS)+1)
ood.dens[rpd]=(ood.dens[rpd]or 0)+opd
end
local spd=workspace._BASES.player:FindFirstChild(bbf[5239])
local tpd=spd and spd:FindFirstChild(bbf[5240])
local upd=tpd and tpd:FindFirstChildOfClass(bbf[3046])
if upd then
ood.baseHp=math.max(ood.baseHp or 0,upd.MaxHealth)
local vpd=0
for wpd,xpd in ipairs(bb.enemies)do
if xpd.prog>=0.97 then
