vpd=vpd+(ypd and ypd.MaxHealth or xpd.hp)
end
end
if ood.lastBase and upd.Health<ood.lastBase and vpd>0 and ood.lastBaseT then
table.insert(ood.baseRel,(ood.lastBase-upd.Health)/math.max(0.1,qod-ood.lastBaseT)/vpd)
end
ood.lastBase,ood.lastBaseT=upd.Health,qod
end
end
function bb.recordMap()
local zpd=bb.mapKey()
local Apd=P.maps[zpd]
if Apd and Apd.v==1 and Apd.laneV and(Apd.densN or 0)==(Apd.binsDensN or 0)then
return
end
if Apd and Apd.v==1 and Apd.laneV and(Apd.densN or 0)>5 and(Apd.binsDensN or 0)>=5 then
return
end
local Bpd={override_hitbox_radius=1.75}
local Cpd={hill_unit=true,override_hitbox_radius=1.75}
local Dpd,Epd={},false
for Fpd,Gpd in ipairs(bb.cands)do
local Hpd=bb.valid(Gpd,Bpd,true)
if Hpd then
table.insert(Dpd,Hpd)
end
if not Epd and bb.valid(Gpd,Cpd,true)then
Epd=true
end
if Fpd%30==0 then
task.wait()
end
end
local Ipd,Jpd={},{}
local Kpd=gb.laneList(bb.samples)
for Lpd=5,60,5 do
local Mpd,Npd
for Opd,Ppd in ipairs(Dpd)do
local Qpd=bb.cover(Ppd,Lpd,true,nil,true)
if not Npd or Qpd>Npd then
Mpd,Npd=Ppd,Qpd
end
end
if Mpd then
local Rpd,Spd={},{}
for Tpd=1,gb.BINS do
Rpd[Tpd]=bbf[4793]
end
for Upd,Vpd in ipairs(Kpd or{})do
Spd[Vpd]={}
for Wpd=1,gb.BINS do
Spd[Vpd][Wpd]=bbf[4793]
end
end
local Xpd=U.flat(Mpd)
for Ypd,Zpd in ipairs(bb.samples)do
if(U.flat(Zpd.pos)-Xpd).Magnitude<=Lpd then
local _pd=math.min(gb.BINS,math.floor(Zpd.prog*gb.BINS)+1)
Rpd[_pd]=bbf[3091]
if Spd[tostring(Zpd.lane)]then
Spd[tostring(Zpd.lane)][_pd]=bbf[3091]
end
end
end
Ipd[tostring(Lpd)]=table.concat(Rpd)
if Kpd then
Jpd[tostring(Lpd)]={}
for aqd,bqd in pairs(Spd)do
Jpd[tostring(Lpd)][aqd]=table.concat(bqd)
end
end
end
task.wait()
end
local cqd=P.maps[zpd]or{}
