bb.REAL_WIN=75
function bb.realK(mtd)
local ntd=bb.realC
local otd=U.now()
if not ntd then
ntd={t=0,k={},snaps={},seen={}}
bb.realC=ntd
end
if otd-ntd.t>=5 then
ntd.t=otd
ntd.k={}
local ptd,qtd,rtd=pcall(bb.damageShares)
local std={}
if ptd and type(qtd)==bbf[2635]and(rtd or 0)>0 then
for ttd,utd in pairs(qtd)do
std[ttd]=utd*rtd
end
end
local vtd,wtd={},0
for xtd,ytd in ipairs(bb.mine or{})do
local ztd=ytd:FindFirstChild(bbf[2707])
local Atd=ztd and ztd:FindFirstChild(bbf[3030])and ztd.id.Value
if Atd and not V.isFarm(Atd)then
local Btd,Ctd=pcall(bb.liveDps,ytd,Atd)
Ctd=Btd and tonumber(Ctd)or 0
vtd[Atd]=(vtd[Atd]or 0)+Ctd
wtd=wtd+Ctd
ntd.seen[Atd]=ntd.seen[Atd]or otd
end
end
table.insert(ntd.snaps,{t=otd,abs=std})
while#ntd.snaps>1 and otd-ntd.snaps[2].t>=bb.REAL_WIN do
table.remove(ntd.snaps,1)
end
local Dtd=ntd.snaps[1]
if otd-Dtd.t>=20 and wtd>0 then
local Etd,Ftd={},0
for Gtd in pairs(vtd)do
local Htd=math.max(0,(std[Gtd]or 0)-(Dtd.abs[Gtd]or 0))
Etd[Gtd]=Htd
Ftd=Ftd+Htd
end
if Ftd>0 then
local Itd
for Jtd,Ktd in pairs(vtd)do
if otd-ntd.seen[Jtd]>=eb.REAL_AGE then
local Ltd=eb.realK(Etd[Jtd]/Ftd,Ktd/wtd,eb.REAL_AGE)
if not Itd or Ltd<Itd then
Itd=Ltd
end
end
end
for Mtd,Ntd in pairs(vtd)do
ntd.k[Mtd]=eb.realK(Etd[Mtd]/Ftd,Ntd/wtd,otd-ntd.seen[Mtd],Itd)
end
end
end
end
return ntd.k[mtd]or 1
end
function bb.upPath(Otd,Ptd,Qtd,Rtd,Std,Ttd,Utd,Vtd)
local Wtd=Ptd[Qtd+1]
local Xtd=eb.shieldGainAhead(Otd,Ptd[Qtd],Ttd(Qtd+1),Wtd,Utd,Vtd)
if Xtd==nil then
return nil
end
local Ytd,Ztd=Xtd/math.max(1,Rtd),Rtd
for _td=Qtd+2,Ptd.max do
local aud=Ptd[_td]
if not aud then
break
end
Ztd=Ztd+(tonumber(aud.cost)or 0)*(Std or 1)
local bud=eb.shieldGainAhead(Otd,Ptd[Qtd],Ttd(_td),aud,Utd,Vtd)
if bud and bud/math.max(1,Ztd)>Ytd then
Ytd=bud/math.max(1,Ztd)
end
end
return Ytd*Rtd
end
function bb.realBlend(cud,dud)
