local VJd=UJd._stats.id.Value
local WJd=not SJd[VJd]and V.allyBuff(VJd)
if WJd and type(WJd.types)==bbf[2635]then
SJd[VJd]=true
local XJd=0
for YJd,ZJd in pairs(WJd.types)do
XJd=math.max(XJd,tonumber(ZJd)or 0)
end
if XJd>0 then
local _Jd=tonumber(bb.buffLevel(WJd.types))or 0
local aKd=bb.buffTrack[VJd]
if not aKd then
aKd={n=0,sum=0,top=0,stacked=0,single=XJd}
bb.buffTrack[VJd]=aKd
end
aKd.n,aKd.sum,aKd.top=aKd.n+1,aKd.sum+_Jd,math.max(aKd.top,_Jd)
if _Jd>XJd+0.05 then
aKd.stacked=aKd.stacked+1
end
aKd.copies=0
for bKd,cKd in ipairs(bb.mine)do
if cKd._stats.id.Value==VJd then
aKd.copies=aKd.copies+1
end
end
end
end
end
end
function bb.buffsRecord()
