dKd[eKd]={casts=gKd and gKd.casts or 0,n=fKd.n,mean=math.floor(fKd.sum/fKd.n*100+0.5),stacked=math.floor(fKd.stacked/fKd.n*100+0.5)/100,top=math.floor(fKd.top*100+0.5),single=math.floor((fKd.single or 0)*100+0.5),copies=fKd.copies}
end
end
return dKd
end
bb.prioAt=setmetatable({},{__mode=bbf[3037]})
