local wKd=vKd:FindFirstChild(bbf[5415])
local xKd=O.community and N.TIPS[vKd.id.Value]and N.TIPS[vKd.id.Value].target
if wKd and wKd.Value~=bbf[3481]and not xKd and bb.canAir(uKd)and not V.isFarm(vKd.id.Value)and not V.allyBuff(vKd.id.Value)and vKd.id.Value~=bbf[4987]and U.now()-(bb.prioAt[uKd]or 0)>8 then
