end
end
end
end
mb.CARD_PICKS={bbf[1553],bbf[2653],bbf[3234],bbf[1556]}
function mb.cardPearls(YKd,ZKd)
local _Kd=mb.pearlsFrom((tonumber(ZKd)or 0)+1,50)
local aLd=0
for bLd,cLd in pairs(type(YKd)==bbf[2635]and type(YKd.effects)==bbf[2635]and YKd.effects or{})do
if type(cLd)==bbf[2635]and cLd.type==bbf[3216]then
aLd=aLd+math.abs(tonumber(cLd.amount)or 0)*_Kd
end
end
return aLd
end
function mb.cardLuck(dLd)
local eLd=0
for fLd,gLd in pairs(type(dLd)==bbf[2635]and type(dLd.effects)==bbf[2635]and dLd.effects or{})do
if type(gLd)==bbf[2635]and gLd.type==bbf[3219]then
eLd=eLd+(tonumber(gLd.amount)or 0)
end
end
return eLd
end
function bb.huntChoose(hLd,iLd)
bb.fhP=bb.fhP or 1
local jLd=mb.floor()
local kLd=(bb.pressure or 0)>=O.safeReach or(bb.depth and bb.depth.leak)
local lLd=mb.weatherStrength(mb.weatherNow())
local mLd=table.find(mb.CARD_PICKS,O.huntCards)and O.huntCards or bbf[1556]
local nLd,oLd,pLd,qLd
local rLd={}
bb.fhFactors={}
for sLd,tLd in pairs(hLd)do
local uLd,vLd=1,{}
for wLd,xLd in pairs(type(tLd)==bbf[2635]and tLd.effects or{})do
if type(xLd)==bbf[2635]then
local yLd=bb.rogueEffect(xLd)
uLd=uLd*yLd
table.insert(vLd,bb.effectText(xLd))
end
end
if type(tLd)==bbf[2635]and tLd.weather then
uLd=uLd*mb.weatherStrength(tLd.weather)/math.max(0.05,lLd)
end
if type(tLd)==bbf[2635]and(tLd.title or tLd.name)then
bb.fhFactors[tostring(tLd.title or tLd.name):lower():gsub(bbf[5427],bbf[1551])]=uLd
end
local zLd=type(tLd)==bbf[2635]and mb.cardGems(tLd,iLd)or 0
local ALd=uLd>=1 or(bb.fhP*uLd>=jLd and not kLd)
local BLd=math.log(math.max(0.05,uLd))
local CLd=BLd*mb.STRENGTH_GEMS+(ALd and zLd or-1000)
local DLd=mb.cardLuck(tLd)
if mLd==bbf[1553]and ALd and DLd>0 then
CLd=2e6+DLd*1e4+zLd
elseif mLd==bbf[2653]and ALd then
CLd=1e6+mb.cardPearls(tLd,iLd)*10+zLd+BLd
elseif mLd==bbf[3234]then
CLd=BLd*1e6+zLd
end
if not oLd or CLd>oLd then
nLd,oLd,pLd,qLd=sLd,CLd,uLd,zLd
end
table.insert(rLd,string.format(bbf[5428],tostring(sLd),tostring(type(tLd)==bbf[2635]and tLd.title or bbf[2888]),(type(tLd)==bbf[2635]and tLd.weather)and(bbf[3389]..tostring(tLd.weather)..bbf[3175])or bbf[1551],tostring(type(tLd)==bbf[2635]and tLd.option_type or bbf[2888]),uLd,math.floor(zLd+0.5),table.concat(vLd,bbf[3304])))
end
return nLd,pLd,qLd,rLd,jLd,kLd,mLd
end
function bb.huntPick(ELd)
