local RLd= #H:GetPlayers()>1
F.log(1,bbf[5432],string.format(bbf[5433],FLd,RLd and bbf[5434]or bbf[5435],tostring(GLd),tostring(MLd),math.floor((ILd or 0)+0.5),QLd>0 and string.format(bbf[5436],QLd)or bbf[1551],bb.fhP,KLd,LLd and bbf[5437]or bbf[1551],table.concat(JLd,bbf[4618])))
