bb.HUNT_WEAK_RUNS=8
bb.HUNT_WEAK_KINDS={bbf[2659],bbf[2656],bbf[2660],bbf[2657],bbf[2661],bbf[3115],bbf[4274],bbf[2655],bbf[2654],bbf[3106]}
function bb.huntWeakText()
local iMd=type(P.hunt)==bbf[2635]and P.hunt.runs or{}
if#iMd<bb.HUNT_WEAK_RUNS then
return nil
end
local jMd,kMd,lMd=0,0,{}
for mMd=1,bb.HUNT_WEAK_RUNS do
local nMd=iMd[mMd]
if type(nMd)~=bbf[2635]or nMd.won then
return nil
end
jMd,kMd=jMd+(tonumber(nMd.pearls)or 0),kMd+(tonumber(nMd.sec)or 0)
table.insert(lMd,tonumber(nMd.wave)or 0)
end
if kMd<=0 then
return nil
end
table.sort(lMd)
local oMd=lMd[math.ceil(#lMd/2)]
local pMd=jMd/kMd*60*(tonumber(O.pearlValue)or 0.35)
local qMd={string.format(bbf[5451],bb.HUNT_WEAK_RUNS,oMd,pMd)}
local rMd
for sMd,tMd in ipairs(W.lastScored or{})do
if tMd.kind~=bbf[2658]and(tonumber(tMd.score)or 0)>0 then
rMd=tMd
break
end
end
if rMd then
table.insert(qMd,string.format(bbf[5452],tostring(rMd.label),rMd.score))
end
local uMd=0
for vMd,wMd in ipairs(bb.HUNT_WEAK_KINDS)do
if O[wMd]==false then
uMd=uMd+1
end
end
if W.onlyOn()then
table.insert(qMd,bbf[5453])
elseif uMd>=4 then
table.insert(qMd,string.format(bbf[5454],uMd))
end
table.insert(qMd,bbf[5455])
return table.concat(qMd,bbf[3028]),pMd,oMd
end
