function bb.pickRogue()
local yMd=bb.rogueOptions
if yMd and bb.hunt then
return bb.huntPick(yMd)
end
if not yMd then
local zMd=F.request(bbf[5431],bbf[4435],1)
return zMd
end
bb.fhP=bb.fhP or 1
local AMd=tonumber(P.fh.pmin)or 1
local BMd=(bb.pressure or 0)>=O.safeReach or(bb.depth and bb.depth.leak)
local CMd,DMd,EMd
for FMd,GMd in pairs(yMd)do
local HMd,IMd=1,0
for JMd,KMd in pairs(type(GMd)==bbf[2635]and GMd.effects or{})do
if type(KMd)==bbf[2635]then
local LMd,MMd=bb.rogueEffect(KMd)
HMd=HMd*LMd
IMd=IMd+MMd
end
end
local NMd=math.log(math.max(0.05,HMd))*10
if IMd>0 and bb.fhP*HMd>=AMd and not BMd then
NMd=NMd+100*IMd
elseif IMd>0 then
NMd=NMd-50+IMd
end
if not DMd or NMd>DMd then
CMd,DMd,EMd=FMd,NMd,HMd
end
end
bb.fhP=bb.fhP*(EMd or 1)
local OMd={}
for PMd,QMd in pairs(yMd)do
local RMd={}
for SMd,TMd in pairs(type(QMd)==bbf[2635]and QMd.effects or{})do
if type(TMd)==bbf[2635]then
table.insert(RMd,bb.effectText(TMd))
end
end
table.insert(OMd,tostring(PMd)..bbf[5456]..table.concat(RMd,bbf[3304]))
end
bb.rogueOptions=nil
local UMd=F.request(bbf[5431],bbf[4435],CMd)
F.log(1,bbf[5432],string.format(bbf[5457],bb.wave(),tostring(CMd),DMd or 0,bb.fhP,AMd,table.concat(OMd,bbf[4618])))
return UMd
end
function bb.rogueShare(VMd)
if not VMd then
return 0.5
end
local WMd=tostring(VMd):gsub(bbf[4645],bbf[1551])
local XMd,YMd=0,0
for ZMd,_Md in ipairs(bb.mine or{})do
local aNd=_Md._stats.id.Value
if not V.isFarm(aNd)then
local bNd,cNd=pcall(bb.liveDps,_Md,aNd)
cNd=bNd and cNd or 0
local dNd=V.types(aNd)
XMd=XMd+cNd
if dNd[WMd]or dNd[WMd..bbf[2856]]then
YMd=YMd+cNd
end
end
end
local eNd=0
for fNd,gNd in ipairs(bb.mine or{})do
if not V.isFarm(gNd._stats.id.Value)then
eNd=eNd+1
end
end
local hNd=eNd/(eNd+4)
return hNd*(XMd>0 and YMd/XMd or 0.5)+(1-hNd)*0.5
end
function bb.resistOf(iNd)
local jNd=V.types(iNd)
local kNd=0
for lNd,mNd in pairs(bb.fhResist or{})do
local nNd=tostring(lNd):gsub(bbf[4645],bbf[1551])
if jNd[nNd]or jNd[nNd..bbf[2856]]then
kNd=math.max(kNd,mNd/100)
end
end
return math.min(0.95,kNd)
end
function bb.rogueEffect(oNd)
local pNd,qNd,rNd=oNd.type,tonumber(oNd.amount)or 0,tostring(oNd.stat or bbf[1551])
if pNd==bbf[3216]then
return 1,math.abs(qNd)
end
if pNd==bbf[4782]or pNd==bbf[4787]or pNd==bbf[4783]then
if rNd==bbf[3087]then
return math.max(0.3,1+qNd),0
end
if rNd==bbf[2905]then
return math.max(0.5,1+qNd/2),0
end
if rNd:find(bbf[3472])then
return 1/math.max(0.3,1+qNd),0
end
return 1,0
end
if pNd==bbf[5458]then
if rNd==bbf[3087]then
return math.max(0.3,qNd),0
end
if rNd==bbf[2905]then
return math.max(0.5,1+(qNd-1)/2),0
end
if rNd:find(bbf[3472])then
return 1/math.max(0.3,qNd),0
end
return 1,0
end
if pNd==bbf[4789]then
return 1+qNd/3,0
end
if pNd==bbf[4795]then
return 1/math.max(0.3,1+qNd),0
end
if pNd==bbf[5459]then
return math.max(0.2,1-bb.rogueShare(oNd.damage_type)*(1-100/(100+qNd))),0
end
if pNd==bbf[5460]then
return 1+bb.rogueShare(oNd.damage_type)*qNd,0
end
if pNd==bbf[5461]then
return math.max(0.5,1-qNd*0.5),0
end
if pNd==bbf[5462]then
return math.max(0.5,1-qNd*0.2),0
end
if pNd==bbf[5463]then
return 1+qNd*0.1,0
end
if pNd==bbf[5464]then
return 1/math.max(0.3,1+qNd*0.5),0
end
if pNd==bbf[5465]then
return math.max(0.5,1-qNd*0.1),0
end
if pNd==bbf[4790]then
return 1/math.max(0.3,1+qNd),0
end
if pNd==bbf[4796]then
return math.max(0.3,1-qNd*20),0
end
if pNd==bbf[4797]then
return math.max(0.5,1-qNd*0.03),0
end
if pNd==bbf[5466]then
return 0.95,0
end
if pNd==bbf[4798]then
return math.max(0.5,1-qNd),0
end
if pNd==bbf[5467]then
return 1+math.min(0.3,qNd/40000),0
end
if pNd==bbf[4791]then
return 1/math.max(0.3,1+qNd/2),0
end
if pNd==bbf[5468]then
return 0.8,0
end
if pNd==bbf[5469]then
local sNd=math.max(1,math.abs(qNd))*math.max(1,math.abs(tonumber(oNd.tier)or 1))
return oNd._type==bbf[5470]and 1.1^sNd or 0.8^sNd,0
end
return 1,0
end
function bb.effectText(tNd)
