vNd[xNd.id]=(vNd[xNd.id]or 0)+(tonumber(xNd.v)or 0)
end
end
for yNd,zNd in pairs(bb.helperDealt or{})do
if zNd.owner and V.SUMMONER[zNd.owner]and not V.droneHelper(zNd)then
vNd[zNd.owner]=(vNd[zNd.owner]or 0)+(tonumber(zNd.v)or 0)
