function bb.summonWorth()
if bb.summonAvg==nil then
local HRd,IRd,JRd=0,0,0
for KRd,LRd in ipairs(V.equipped())do
local MRd,NRd=pcall(V.dps,LRd.u,0,bb.mod)
HRd,IRd,JRd=HRd+((not V.isFarm(LRd.id)and MRd and NRd)or 0),IRd+1,JRd+(LRd.data.cost or 0)
end
bb.summonAvg,bb.summonCost=IRd>0 and HRd/IRd or 0,IRd>0 and JRd/IRd or 0
end
local ORd=bb.bestRate or 0
return ORd<=0 or bb.summonAvg*2>=ORd*(10000+bb.summonCost)
end
function bb.hasGeneral()
