local XRd,YRd=pcall(bb.liveDps,VRd,WRd)
if XRd and YRd and YRd>0 then
table.insert(TRd,{m=VRd,dps=YRd})
end
end
end
if#TRd<3 then
return nil
end
table.sort(TRd,function(ZRd,_Rd)
return ZRd.dps>_Rd.dps
end)
local aSd=bb.ritualWorth()
if not aSd then
return TRd[3].m,bbf[5511]
end
if aSd>=1.5 then
return TRd[1].m,string.format(bbf[5512],aSd)
end
return nil
end
