function bb.adaptNext(lSd,mSd)
for nSd,oSd in ipairs(bb.ADAPT_ORDER)do
local pSd=mSd[oSd]
if pSd and not lSd:GetAttribute(pSd)then
return oSd,pSd
end
end
local qSd={}
for rSd,sSd in pairs(mSd)do
if not lSd:GetAttribute(sSd)then
table.insert(qSd,rSd)
end
end
table.sort(qSd)
if qSd[1]then
return qSd[1],mSd[qSd[1]]
end
