bb.adaptPrompt=nil
local DSd=M:FindFirstChild(bbf[5516])
for ESd,FSd in ipairs(DSd and DSd:GetDescendants()or{})do
if FSd.Name==bbf[5517]and not FSd:FindFirstAncestorOfClass(bbf[5531])then
bb.adaptPrompt=FSd
break
end
end
end
local GSd=bb.adaptPrompt
if not(GSd and GSd:IsA(bbf[5532])and GSd.Visible)then
bb.adaptTries=0
