end
for KSd,LSd in ipairs(bb.ADAPT_ORDER)do
local MSd=HSd[LSd]
local NSd=MSd and(MSd:IsA(bbf[5533])and MSd or MSd:FindFirstChildWhichIsA(bbf[5533],true))
if NSd and MSd.Visible then
local OSd=0
for PSd,QSd in ipairs({NSd.Activated,NSd.MouseButton1Click,NSd.MouseButton1Down})do
for RSd,SSd in ipairs(getconnections(QSd))do
if pcall(function()
SSd:Fire()
end)then
OSd=OSd+1
