function bb.refund()
local _Td=N.session()
if not(bb.random and _Td)or bb.spellBusy or bb.roomPlan or not ab.every(bbf[5553],20)then
return
end
local aUd
for bUd,cUd in pairs(_Td.ingame_spells or{})do
if cUd==bbf[5540]then
aUd=bUd
end
end
if not aUd then
return
end
local dUd=(bb.pressure or 0)>=math.min(O.dangerReach,((bb.depth and bb.depth.units>0 and bb.depth.covEnd)or 1)*0.9)
local eUd=bb.bestRate or 0
if dUd or eUd<=0 then
return
end
local fUd=bb.wave()
local gUd=math.max(0,(bb.total or 30)-fUd)
local hUd=bb.mergePlan
local iUd=bb.airLow()
local jUd,kUd,lUd
for mUd,nUd in ipairs(bb.mine)do
local oUd=nUd._stats
local pUd=oUd.id.Value
local qUd=N.Units[pUd]
local rUd=oUd:FindFirstChild(bbf[5009])and tonumber(oUd.total_spent.Value)or 0
if qUd and not qUd.unsellable and rUd>0 and not V.allyBuff(pUd)and not V.idol(pUd)and not(hUd and hUd.id==pUd)then
local sUd,tUd
if V.isFarm(pUd)then
local uUd=oUd:FindFirstChild(bbf[2755])and tonumber(oUd.farm_amount.Value)or 0
local vUd=uUd*gUd
if rUd>vUd*1.2 then
sUd=(rUd-vUd)*eUd
tUd=string.format(bbf[5554],U.fmt(vUd),U.fmt(rUd))
end
elseif fUd>=10 and gUd>2 and rUd>=5000 and(bb.upRate[nUd]or 0)<eUd/3 and bb.progressAt(nUd:GetPivot().Position)<0.8 and not(iUd and bb.canAir(nUd))then
local wUd,xUd=pcall(bb.liveDps,nUd,pUd)
xUd=wUd and xUd or math.huge
if rUd*eUd>3*xUd and xUd<0.1*(bb.teamDps or 0)then
sUd=rUd*eUd-xUd
tUd=string.format(bbf[5555],U.fmt(rUd))
end
end
if sUd and(not kUd or sUd>kUd)then
jUd,kUd,lUd=nUd,sUd,tUd
end
end
end
if not jUd then
return
end
bb.spellBusy=true
task.spawn(function()
local yUd=V.name(jUd._stats.id.Value)
local zUd=F.request(bbf[5546],bbf[5547],aUd,jUd)
task.wait(1.5)
if zUd and(N.session().ingame_spells or{})[aUd]~=bbf[5540]then
bb.refunds=(bb.refunds or 0)+1
F.log(1,bbf[5526],string.format(bbf[5556],yUd,lUd))
F.status(bbf[5410],bbf[5557]..yUd)
else
F.backoff(bbf[5546],15)
F.log(2,bbf[5526],bbf[5558]..yUd)
end
bb.spellBusy=false
end)
end
bb.BASE_WIN,bb.BASE_MARGIN,bb.BASE_SOON,bb.BASE_END=10,1.3,45,0.97
function bb.baseVerdict(AUd,BUd)
local CUd=(BUd.t or 0)-(AUd.t or 0)
if CUd<bb.BASE_WIN-1 then
return false
end
local DUd=((tonumber(AUd.base)or 0)-(tonumber(BUd.base)or 0))/CUd
if DUd<=0 or(tonumber(BUd.base)or 0)<=0 then
return false
end
local EUd=BUd.base/DUd
local FUd,GUd=0,0
local HUd,IUd=AUd.foes or{},BUd.foes or{}
for JUd,KUd in pairs(IUd)do
if KUd.prog>=bb.BASE_END then
FUd=FUd+KUd.hp
local LUd=HUd[JUd]
if LUd then
GUd=GUd+math.max(0,LUd.hp-KUd.hp)
end
end
end
for MUd,NUd in pairs(HUd)do
if NUd.prog>=bb.BASE_END and not IUd[MUd]then
GUd=GUd+NUd.hp
end
end
if FUd<=0 then
return false
end
local OUd=GUd/CUd
local PUd=OUd>0 and FUd/OUd or math.huge
local QUd={baseTime=EUd,loss=DUd,atEnd=FUd,rate=OUd,killTime=PUd}
return EUd<bb.BASE_SOON and PUd>EUd*bb.BASE_MARGIN,QUd
end
