end
local MVd=workspace:FindFirstChild(bbf[5570])and workspace._BASES:FindFirstChild(bbf[4966])
local NVd=MVd and MVd:FindFirstChild(bbf[5239])and MVd.base:FindFirstChild(bbf[5240])
local OVd=NVd and NVd:FindFirstChildOfClass(bbf[3046])
if not OVd or OVd.Health<=0 then
return
end
local PVd=(bb.info and tonumber(bb.info.baseRel))or gb.PRIOR.baseRel
local QVd=U.now()
bb.leakTrack=bb.leakTrack or{}
local RVd=bb.leakTrack
