for UVd,VVd in ipairs(bb.enemies or{})do
if VVd.m then
SVd[VVd.m]=true
local WVd,XVd=tonumber(VVd.hp)or 0,tonumber(VVd.prog)or 0
local YVd=RVd[VVd.m]
local ZVd=tonumber(VVd.sh)or 0
if not YVd then
RVd[VVd.m]={t=QVd,hp=WVd,prog=XVd,sh=ZVd}
else
if QVd-YVd.t>=bb.LEAK_WIN then
local _Vd=(XVd-YVd.prog)/(QVd-YVd.t)
if _Vd>bb.paceCap()then
_Vd=YVd.pace
end
YVd.pace,YVd.net=_Vd,(YVd.hp-WVd)/(QVd-YVd.t)
YVd.strip=(tonumber(YVd.sh)or 0)>ZVd
YVd.t,YVd.hp,YVd.prog,YVd.sh=QVd,WVd,XVd,ZVd
end
local aWd=bb.baseStuds(VVd.m,NVd)
local bWd=bb.bailLine()
local cWd=bb._lastLifeRun and YVd.pace and YVd.pace>0 and(1-XVd)/YVd.pace<=bb.LEAK_AHEAD or false
if cWd then
