if dWd and not eWd then
cWd=false
end
end
if aWd and(aWd<=bWd or cWd)and WVd>0 then
local fWd=cWd and(1-XVd)/YVd.pace or bb.BOSS_OUT
local gWd=math.max(0,YVd.net or 0)
local hWd=WVd-gWd*fWd
if hWd>0 then
local iWd=VVd.m:FindFirstChildOfClass(bbf[3046])
local jWd=OVd.Health/math.max(1,PVd*(iWd and iWd.MaxHealth or WVd))
local kWd=gWd>0 and hWd/gWd or math.huge
