end
end
end
end
end
end
for mWd in pairs(RVd)do
if not SVd[mWd]then
RVd[mWd]=nil
end
end
if KVd then
return TVd~=nil,TVd
end
if not TVd then
return
end
bb.bailNote(LVd,bbf[5248])
F.log(1,bbf[3339],string.format(bbf[5573],bb.wave(),tonumber(bb.total)or 0,math.floor(TVd.studs+0.5),U.fmt(TVd.hp),U.fmt(TVd.net),TVd.baseTime))
