bb.toLobby(bbf[5572])
end
bb.FOCUS_MAX=8
bb.coverMax=setmetatable({},{__mode=bbf[3037]})
function bb.allPast(nWd)
local oWd={}
for pWd,qWd in ipairs(bb.mine or{})do
local rWd=qWd._stats
local sWd=rWd.id.Value
if not V.isFarm(sWd)and not V.allyBuff(sWd)and rWd:FindFirstChild(bbf[2905])then
local tWd=tonumber(rWd.range.Value)or 0
local uWd=bb.coverMax[qWd]
if not(uWd and uWd.r==tWd)then
local vWd,wWd=U.flat(qWd:GetPivot().Position),-1
for xWd,yWd in ipairs(bb.samples or{})do
if yWd.prog>wWd and(U.flat(yWd.pos)-vWd).Magnitude<=tWd then
wWd=yWd.prog
end
end
uWd={r=tWd,far=wWd}
bb.coverMax[qWd]=uWd
end
table.insert(oWd,{far=uWd.far,air=bb.canAir(qWd)})
end
end
if#oWd==0 then
return false
end
for zWd,AWd in ipairs(nWd)do
for BWd,CWd in ipairs(oWd)do
if(not AWd.fly or CWd.air)and CWd.far>=(tonumber(AWd.prog)or 0)then
return false
end
end
end
return true
end
function bb.fbTick()
