local MWd=(LWd and LWd.MaxHealth>0)and LWd.MaxHealth or GWd.hp
local NWd=(N.Units[FWd]and N.Units[FWd].name)or FWd
if not KWd or KWd.m~=GWd.m then
KWd={m=GWd.m,id=FWd,name=NWd,wave=bb.wave(),t0=U.now(),max=MWd,low=1,assassin=DWd.assassin,beatAt=tonumber(DWd.beatAt)or 0.5,walk=DWd.walk}
bb.fb=KWd
if DWd.assassin then
