function bb.focusSpot(zYd)
local AYd=bb.focus
local BYd=V.range(zYd.u,0)*((bb.info and bb.info.rangeScale)or 1)
local CYd=U.flat(AYd.pos)
local DYd,EYd
local FYd=0
for GYd,HYd in ipairs(bb.cands)do
if(U.flat(HYd)-CYd).Magnitude<=BYd then
local IYd=bb.valid(HYd,zYd.data)
FYd=FYd+1
if FYd%40==0 then
task.wait()
end
if IYd then
local JYd,KYd=0,U.flat(IYd)
for LYd,MYd in ipairs(bb.hurtSamples())do
if MYd.prog>=AYd.prog and(U.flat(MYd.pos)-KYd).Magnitude<=BYd then
JYd=JYd+1
end
end
if not EYd or JYd>EYd then
DYd,EYd=IYd,JYd
end
end
end
end
return DYd,EYd or 0
end
function bb.focusGain(NYd)
local OYd=bb.focus
if not OYd then
return 1
end
local PYd=NYd._stats
if not PYd:FindFirstChild(bbf[2905])then
return 1
end
local QYd,RYd=U.flat(NYd:GetPivot().Position),PYd.range.Value
if OYd.fly and not bb.canAir(NYd)then
return 0.02
end
if(QYd-U.flat(OYd.pos)).Magnitude<=RYd then
return 1
end
if OYd.box then
for SYd,TYd in ipairs(bb.samples or{})do
if TYd.prog>OYd.prog and(U.flat(TYd.pos)-QYd).Magnitude<=RYd then
return 1
end
end
end
return(QYd-U.flat(OYd.pos)).Magnitude<=RYd*1.5 and 0.3 or 0.02
end
